import axios from 'axios';
import { getAccessToken, getRefreshToken, setTokens, clearTokens } from '../auth/tokenStorage';

const client = axios.create({
  baseURL: import.meta.env.VITE_API_URL,
  timeout: 10000,
});

function getCookie(name) {
  const value = `; ${document.cookie}`;
  const parts = value.split(`; ${name}=`);
  if (parts.length === 2) return parts.pop().split(';').shift();
  return null;
}

client.interceptors.request.use((config) => {
  const token = getAccessToken();
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }

  const csrfToken = getCookie('csrftoken');
  if (csrfToken) {
    config.headers['X-CSRFToken'] = csrfToken;
  }

  return config;
});

let refreshPromise = null;

// SIMPLE_JWT est configuré avec ROTATE_REFRESH_TOKENS=True et
// BLACKLIST_AFTER_ROTATION=True côté backend : chaque rafraîchissement
// renvoie un NOUVEAU refresh token et blackliste l'ancien. Il faut donc
// bien persister les deux valeurs à chaque appel, sous peine que le
// rafraîchissement suivant échoue (refresh token déjà blacklisté).
async function refreshAccessToken() {
  const refresh = getRefreshToken();
  if (!refresh) throw new Error('Aucun refresh token disponible.');

  // Requête axios brute (pas `client`) pour ne pas redéclencher cet
  // intercepteur en boucle sur un 401 de /token/refresh/ lui-même.
  const response = await axios.post(`${import.meta.env.VITE_API_URL}/token/refresh/`, { refresh });
  setTokens({ access: response.data.access, refresh: response.data.refresh });
  return response.data.access;
}

function getErrorMessage(error) {
  const { response, code, message } = error;

  if (response?.status === 401) return 'Session expirée. Veuillez vous reconnecter.';
  if (response?.status === 403) return 'Accès refusé. Vous n\'avez pas la permission.';
  if (response?.status === 404) return 'Ressource non trouvée.';
  if (response?.status === 422) {
    const errors = response.data?.errors || response.data?.detail;
    if (errors) return typeof errors === 'string' ? errors : 'Veuillez vérifier vos données.';
  }
  if (response?.status >= 500) return 'Erreur serveur. Veuillez réessayer plus tard.';
  if (response?.status >= 400) return response.data?.detail || 'Une erreur s\'est produite.';
  if (code === 'ECONNABORTED') return 'La demande a pris trop longtemps. Veuillez réessayer.';
  if (code === 'ENOTFOUND' || code === 'ECONNREFUSED') return 'Impossible de se connecter au serveur.';
  if (message === 'Network Error') return 'Erreur réseau. Vérifiez votre connexion.';

  return 'Une erreur inattendue s\'est produite.';
}

client.interceptors.response.use(
  (response) => response,
  async (error) => {
    const { config, response } = error;
    const isAuthEndpoint = config?.url?.includes('/token/');

    if (response?.status === 401 && !config._retry && !isAuthEndpoint) {
      config._retry = true;
      refreshPromise ??= refreshAccessToken().finally(() => {
        refreshPromise = null;
      });

      try {
        const newAccess = await refreshPromise;
        config.headers.Authorization = `Bearer ${newAccess}`;
        return client(config);
      } catch {
        clearTokens();
        // Rechargement complet plutôt qu'un appel à AuthContext : cet
        // intercepteur vit en dehors de l'arbre React et n'a pas accès à
        // son state.
        if (window.location.pathname !== '/login') {
          window.location.assign('/login');
        }
      }
    }

    // Global error logging (ne rejette pas encore, juste pour la visibilité)
    const errorMsg = getErrorMessage(error);
    if (import.meta.env.DEV) {
      console.error(`API Error [${config?.method?.toUpperCase()} ${config?.url}]:`, {
        status: response?.status,
        message: errorMsg,
        data: response?.data,
        error: error.message,
      });
    }

    // Attacher le message utilisateur-friendly à l'erreur
    error.userMessage = errorMsg;
    return Promise.reject(error);
  }
);

export default client;

import client from '../client';

// GET /api/signalements/ — paginé, results est une FeatureCollection GeoJSON.
export function getSignalements({ page } = {}) {
  return client.get('/signalements/', { params: { page } }).then((r) => r.data);
}

// POST /api/signalements/ — AllowAny, mais géré via multipart/form-data car
// la photo (optionnelle) est un vrai fichier. `localisation` accepte la
// forme "lon,lat" en texte d'après SignalementCitoyenSerializer.to_internal_value.
export function createSignalement({ description, categorie, longitude, latitude, photo }) {
  const formData = new FormData();
  formData.append('description', description);
  formData.append('categorie', categorie);
  formData.append('localisation', `${longitude},${latitude}`);
  if (photo) formData.append('photo', photo);

  return client
    .post('/signalements/', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    })
    .then((r) => r.data);
}

// PATCH /api/signalements/{id}/valider/ — IsAutoriteOrAdmin.
export function validerSignalement(id, valide) {
  return client.patch(`/signalements/${id}/valider/`, { valide }).then((r) => r.data);
}

import { z } from 'zod';

export const authSchemas = {
  signup: z.object({
    first_name: z.string().min(1, 'Prénom requis').min(2, 'Min. 2 caractères'),
    last_name: z.string().min(1, 'Nom requis').min(2, 'Min. 2 caractères'),
    username: z.string().min(1, 'Identifiant requis').min(3, 'Min. 3 caractères'),
    email: z.string().email('Email invalide').optional().or(z.literal('')),
    telephone: z.string().min(1, 'Téléphone requis').min(8, 'Téléphone invalide'),
    password: z.string().min(8, 'Min. 8 caractères'),
    password_confirm: z.string().min(8, 'Min. 8 caractères'),
    role: z.enum(['citoyen', 'autorite', 'admin']),
  }).refine(data => data.password === data.password_confirm, {
    message: 'Les mots de passe ne correspondent pas',
    path: ['password_confirm'],
  }),

  login: z.object({
    username: z.string().min(1, 'Identifiant requis'),
    password: z.string().min(1, 'Mot de passe requis'),
  }),

  otp: z.object({
    code: z.string().length(6, 'Le code OTP doit contenir 6 chiffres').regex(/^\d+$/, 'Le code OTP doit être numérique'),
  }),
};

export const profileSchemas = {
  updateProfile: z.object({
    first_name: z.string().min(1, 'Prénom requis'),
    last_name: z.string().min(1, 'Nom requis'),
    telephone: z.string().min(8, 'Téléphone invalide').optional(),
    email: z.string().email('Email invalide').optional().or(z.literal('')),
  }),

  updatePassword: z.object({
    old_password: z.string().min(1, 'Ancien mot de passe requis'),
    new_password: z.string().min(8, 'Min. 8 caractères'),
    confirm_password: z.string().min(8, 'Min. 8 caractères'),
  }).refine(data => data.new_password === data.confirm_password, {
    message: 'Les mots de passe ne correspondent pas',
    path: ['confirm_password'],
  }),
};

export const signalementSchemas = {
  create: z.object({
    description: z.string().min(10, 'Min. 10 caractères').max(1000, 'Max. 1000 caractères'),
    type_cible: z.enum(['inondation', 'route_fermee', 'refuge', 'autre']),
    zone: z.number().min(1, 'Zone requise'),
    photos: z.array(z.string()).optional(),
  }),
};

export const alerteSchemas = {
  create: z.object({
    titre: z.string().min(1, 'Titre requis').max(100, 'Max. 100 caractères'),
    message: z.string().min(10, 'Min. 10 caractères').max(500, 'Max. 500 caractères'),
    niveau: z.enum(['vert', 'jaune', 'orange', 'rouge']),
    zone: z.number().min(1, 'Zone requise').optional(),
  }),
};

export function validateForm(schema, data) {
  try {
    const validated = schema.parse(data);
    return { success: true, data: validated, errors: {} };
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = {};
      error.errors.forEach(err => {
        const path = err.path.join('.');
        errors[path] = err.message;
      });
      return { success: false, errors };
    }
    return { success: false, errors: { form: 'Erreur de validation' } };
  }
}

import { useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Eye, EyeOff, AlertCircle } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function AdminRegisterPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { darkMode } = useTheme();
  const { showToast } = useToast();

  const code = searchParams.get('code') || '';
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const [formData, setFormData] = useState({
    code: code,
    email: '',
    telephone: '',
    password: '',
    password_confirm: '',
    first_name: '',
    last_name: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.code.trim()) newErrors.code = 'Code d\'invitation requis';
    if (!formData.first_name.trim()) newErrors.first_name = 'Prénom requis';
    if (!formData.last_name.trim()) newErrors.last_name = 'Nom requis';
    if (!formData.email.trim()) newErrors.email = 'Email requis';
    else if (!formData.email.includes('@')) newErrors.email = 'Email invalide';
    if (!formData.telephone.trim()) newErrors.telephone = 'Numéro de téléphone requis';
    if (!formData.password) newErrors.password = 'Mot de passe requis';
    if (formData.password.length < 8) newErrors.password = 'Min. 8 caractères';
    if (formData.password !== formData.password_confirm) {
      newErrors.password_confirm = 'Les mots de passe ne correspondent pas';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setLoading(true);
    try {
      const response = await client.post('/users/admin-register/', {
        code: formData.code,
        email: formData.email,
        password: formData.password,
        first_name: formData.first_name,
        last_name: formData.last_name,
        telephone: formData.telephone,
      });

      showToast('Compte admin créé avec succès !', 'success');

      setTimeout(() => {
        navigate('/login');
      }, 1500);
    } catch (error) {
      const errorData = error.response?.data || {};
      if (typeof errorData === 'object') {
        setErrors(errorData);
      } else {
        showToast(errorData.detail || 'Erreur lors de la création du compte', 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <Logo size="lg" />
          <p className={`text-sm ${darkMode ? 'text-navy-400' : 'text-navy-600'} mt-2`}>
            Créer un compte administrateur
          </p>
        </div>

        {!code && (
          <div className={`flex items-start gap-3 p-4 rounded-lg mb-6 ${darkMode ? 'bg-red-900/20 border border-red-700' : 'bg-red-50 border border-red-200'}`}>
            <AlertCircle size={20} className="text-red-500 flex-shrink-0 mt-0.5" />
            <div className={`text-sm ${darkMode ? 'text-red-300' : 'text-red-700'}`}>
              Accès réservé. Vous devez posséder un code d'invitation valide.
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
              Code d'invitation
            </label>
            <input
              type="text"
              name="code"
              value={formData.code}
              onChange={handleChange}
              placeholder="Entrez le code d'invitation"
              readOnly={!!code}
              className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'} ${code ? 'opacity-70' : ''}`}
            />
            {errors.code && <p className="text-xs text-red-500">{errors.code}</p>}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <input
                type="text"
                name="first_name"
                value={formData.first_name}
                onChange={handleChange}
                placeholder="Prénom"
                className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
              />
              {errors.first_name && <p className="text-xs text-red-500">{errors.first_name}</p>}
            </div>
            <div>
              <input
                type="text"
                name="last_name"
                value={formData.last_name}
                onChange={handleChange}
                placeholder="Nom"
                className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
              />
              {errors.last_name && <p className="text-xs text-red-500">{errors.last_name}</p>}
            </div>
          </div>

          <div>
            <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
              Email <span className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-500'}`}>(Requis)</span>
            </label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="email@exemple.com"
              className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            {errors.email && <p className="text-xs text-red-500">{errors.email}</p>}
          </div>

          <div>
            <input
              type="tel"
              name="telephone"
              value={formData.telephone}
              onChange={handleChange}
              placeholder="+221 77 000 00 00"
              className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            {errors.telephone && <p className="text-xs text-red-500">{errors.telephone}</p>}
          </div>

          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              name="password"
              value={formData.password}
              onChange={handleChange}
              placeholder="Mot de passe (min. 8 caractères)"
              className={`w-full px-4 py-2 pr-10 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-2.5"
            >
              <Eye size={18} />
            </button>
            {errors.password && <p className="text-xs text-red-500">{errors.password}</p>}
          </div>

          <div className="relative">
            <input
              type={showConfirm ? 'text' : 'password'}
              name="password_confirm"
              value={formData.password_confirm}
              onChange={handleChange}
              placeholder="Confirmer le mot de passe"
              className={`w-full px-4 py-2 pr-10 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            <button
              type="button"
              onClick={() => setShowConfirm(!showConfirm)}
              className="absolute right-3 top-2.5"
            >
              <EyeOff size={18} />
            </button>
            {errors.password_confirm && <p className="text-xs text-red-500">{errors.password_confirm}</p>}
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50"
          >
            {loading ? 'Création...' : 'Créer un compte admin'}
          </button>
        </form>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, CheckCircle } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function ForgotPasswordPage() {
  const navigate = useNavigate();
  const { darkMode } = useTheme();
  const { showToast } = useToast();

  const [userType, setUserType] = useState('citoyen'); // citoyen ou autorite
  const [step, setStep] = useState(1); // 1: input, 2: success
  const [contact, setContact] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const isCitoyen = userType === 'citoyen';
  const contactLabel = isCitoyen ? 'Numéro de téléphone' : 'Email';
  const placeholder = isCitoyen ? '+221 77 000 00 00' : 'email@exemple.com';
  const inputType = isCitoyen ? 'tel' : 'email';

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!contact.trim()) {
      setError(`${contactLabel} requis`);
      return;
    }

    if (!isCitoyen && !contact.includes('@')) {
      setError('Email invalide');
      return;
    }

    setLoading(true);
    try {
      const payload = isCitoyen
        ? { telephone: contact }
        : { email: contact };

      await client.post('/users/password-reset/', payload);
      setStep(2);
      showToast('Instructions de réinitialisation envoyées', 'success');
    } catch (err) {
      setError(err.response?.data?.detail || 'Erreur lors de l\'envoi des instructions');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <button
          onClick={() => navigate('/login')}
          className={`flex items-center gap-2 mb-8 ${darkMode ? 'text-navy-400 hover:text-navy-200' : 'text-navy-600 hover:text-navy-900'} transition`}
        >
          <ArrowLeft size={18} />
          Retour
        </button>

        <div className="text-center mb-8">
          <Logo size="lg" />
          <h1 className={`text-2xl font-bold mt-4 ${darkMode ? 'text-white' : 'text-navy-900'}`}>
            {step === 1 ? 'Mot de passe oublié ?' : isCitoyen ? 'SMS envoyé' : 'Email envoyé'}
          </h1>
        </div>

        {step === 1 ? (
          <>
            {/* Onglets Citoyen/Autorité */}
            <div className="flex bg-navy-50 dark:bg-navy-800 rounded-md p-1 mb-6">
              {['citoyen', 'autorite'].map((type) => (
                <button
                  key={type}
                  onClick={() => {
                    setUserType(type);
                    setContact('');
                    setError('');
                  }}
                  className={`flex-1 text-center py-2 rounded-md text-sm transition-colors ${
                    userType === type
                      ? 'bg-white dark:bg-navy text-navy dark:text-navy-50 font-bold shadow'
                      : 'text-navy-600 dark:text-navy-200 font-semibold'
                  }`}
                >
                  {type === 'citoyen' ? 'Citoyen' : 'Autorité'}
                </button>
              ))}
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <p className={`text-sm ${darkMode ? 'text-navy-300' : 'text-navy-700'} mb-6`}>
                Entrez votre {contactLabel.toLowerCase()} pour recevoir les instructions de réinitialisation.
              </p>

              <div>
                <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
                  {contactLabel}
                </label>
                <input
                  type={inputType}
                  value={contact}
                  onChange={(e) => {
                    setContact(e.target.value);
                    setError('');
                  }}
                  placeholder={placeholder}
                  className={`w-full px-4 py-2 rounded-lg border ${
                    error
                      ? 'border-red-500'
                      : darkMode
                        ? 'border-navy-700 bg-navy-900 text-white'
                        : 'border-navy-200 bg-white'
                  } focus:outline-none focus:ring-2 focus:ring-navy-500`}
                />
                {error && <p className="text-xs text-red-500 mt-1">{error}</p>}
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50"
              >
                {loading ? 'Envoi...' : 'Envoyer les instructions'}
              </button>
            </form>
          </>
        ) : (
          <div className="text-center py-8">
            <CheckCircle size={64} className="text-green-500 mx-auto mb-4" />
            <p className={`text-sm ${darkMode ? 'text-navy-300' : 'text-navy-700'} mb-6`}>
              {isCitoyen
                ? `Un SMS avec les instructions de réinitialisation a été envoyé à ${contact}`
                : `Un email avec les instructions de réinitialisation a été envoyé à ${contact}`}
            </p>
            <p className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-600'} mb-8`}>
              {isCitoyen
                ? 'Vérifiez vos messages SMS dans quelques minutes.'
                : 'Vérifiez votre boîte mail (et les spams) dans quelques minutes.'}
            </p>
            <button
              onClick={() => navigate('/login')}
              className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition"
            >
              Retour à la connexion
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import Logo from '../shared/components/Logo';
import ThemeToggle from '../theme/ThemeToggle';
import { useAuth } from '../auth/AuthContext';
import { homeRouteForRole } from '../auth/RequireAuth';

const ROLES = [
  { id: 'citoyen', label: 'Citoyen', fieldLabel: 'Identifiant', placeholder: 'jeandupont' },
  { id: 'autorite', label: 'Autorite', fieldLabel: 'Identifiant', placeholder: 'jeandupont' },
];

export default function LoginPage() {
  const [tab, setTab] = useState('citoyen');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);
  const [mismatchNotice, setMismatchNotice] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const activeRole = ROLES.find((r) => r.id === tab);
  const from = location.state?.from?.pathname;

  async function handleSubmit(e) {
    e.preventDefault();
    setError(null);
    setMismatchNotice(null);
    setIsSubmitting(true);
    try {
      const actualRole = await login({ username, password });
      const isAutoriteRole = ['autorite', 'admin', 'agent'].includes(actualRole);
      const selectedAutorite = tab === 'autorite';

      if (selectedAutorite !== isAutoriteRole) {
        setError(
          isAutoriteRole
            ? "Error: This is an Authority account. Select Authority tab."
            : "Error: This is a Citizen account. Select Citizen tab."
        );
        setIsSubmitting(false);
        return;
      }

      navigate(from || homeRouteForRole(actualRole), { replace: true });
    } catch {
      setError('Identifiant ou mot de passe incorrect.');
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center px-6 py-12 bg-navy-50 dark:bg-navy-950 relative">
      <ThemeToggle className="absolute top-7 right-8" />

      <div className="w-full max-w-[420px] lg:max-w-[480px]">
        <div className="flex flex-col items-center mb-7 lg:mb-9">
          <Logo size="lg" className="lg:scale-125 lg:mb-2" withSlogan />
        </div>

        <div className="bg-white dark:bg-navy rounded-xl border border-navy-50 dark:border-navy-800 shadow-lg p-7 lg:p-9">
          <div className="flex bg-navy-50 dark:bg-navy-800 rounded-md p-1 mb-5 lg:mb-6">
            {ROLES.map((r) => (
              <button
                key={r.id}
                type="button"
                onClick={() => {
                  setTab(r.id);
                  setUsername('');
                  setPassword('');
                  setError(null);
                  setMismatchNotice(null);
                }}
                className={`flex-1 text-center py-2 rounded-md text-sm transition-colors ${
                  tab === r.id
                    ? 'bg-white dark:bg-navy text-navy dark:text-navy-50 font-bold shadow'
                    : 'text-navy-600 dark:text-navy-200 font-semibold'
                }`}
              >
                {r.label}
              </button>
            ))}
          </div>

          <form onSubmit={handleSubmit} autoComplete="off" className="flex flex-col gap-4 lg:gap-5">
            <label className="block">
              <span className="block text-xs lg:text-sm font-semibold text-navy dark:text-navy-50 mb-1.5">
                {activeRole.fieldLabel}
              </span>
              <input
                type="text"
                required
                autoComplete="off"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder={activeRole.placeholder}
                className="w-full px-3.5 py-2.5 lg:py-3 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-navy dark:text-navy-50 placeholder:text-navy-400 text-sm lg:text-base focus:outline-none focus:border-navy dark:focus:border-navy-50"
              />
            </label>

            <label className="block">
              <span className="block text-xs lg:text-sm font-semibold text-navy dark:text-navy-50 mb-1.5">Mot de passe</span>
              <input
                type="password"
                required
                autoComplete="new-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="........"
                className="w-full px-3.5 py-2.5 lg:py-3 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-navy dark:text-navy-50 text-sm lg:text-base focus:outline-none focus:border-navy dark:focus:border-navy-50"
              />
            </label>

            {tab === 'citoyen' && (
              <div className="text-right -mt-2">
                <Link to="/forgot-password" className="text-xs font-semibold text-red cursor-pointer hover:underline">
                  Mot de passe oublie ?
                </Link>
              </div>
            )}

            {error && (
              <div className="px-3 py-2.5 rounded-md bg-red-50 dark:bg-red/15 text-red-900 dark:text-red-200 text-xs">
                {error}
              </div>
            )}
            {mismatchNotice && (
              <div className="px-3 py-2.5 rounded-md bg-navy-50 dark:bg-navy-800 text-navy dark:text-navy-50 text-xs">
                {mismatchNotice}
              </div>
            )}

            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full py-3 lg:py-3.5 rounded-md bg-navy dark:bg-navy-800 text-white text-sm lg:text-base font-bold disabled:opacity-60"
            >
              {isSubmitting ? 'Connexion...' : 'Se connecter'}
            </button>

            {tab === 'citoyen' && (
              <p className="text-center text-xs text-navy-600 dark:text-navy-200">
                Pas encore de compte ?{' '}
                <Link to="/signup?role=citoyen" className="font-bold text-red hover:underline">
                  Creer un compte citoyen
                </Link>
              </p>
            )}
          </form>
        </div>

        <p className="text-center text-[11px] text-navy-400 mt-5">
          MBEUND MI - Thiaroye-sur-Mer
        </p>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, CheckCircle, Clock } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import { useAuth } from '../auth/AuthContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function OTPVerificationPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const { darkMode } = useTheme();
  const { login } = useAuth();
  const { showToast } = useToast();

  const email = location.state?.email || '';
  const phoneNumber = location.state?.phoneNumber || '';
  const username = location.state?.username || '';

  const [step, setStep] = useState(1); // 1: OTP input, 2: success
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [resendTimer, setResendTimer] = useState(0);

  if (!username) {
    return (
      <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
        <div className="w-full max-w-md text-center">
          <p className={`text-lg font-semibold ${darkMode ? 'text-white' : 'text-navy-900'}`}>
            Erreur : données manquantes
          </p>
          <button
            onClick={() => navigate('/signup')}
            className="mt-4 text-navy-600 dark:text-navy-400 hover:underline"
          >
            Retour à l'inscription
          </button>
        </div>
      </div>
    );
  }

  const handleSubmitOTP = async (e) => {
    e.preventDefault();
    setError('');

    if (!otp.trim()) {
      setError('Code OTP requis');
      return;
    }

    if (otp.length < 6) {
      setError('Le code OTP doit avoir au moins 6 caractères');
      return;
    }

    setLoading(true);
    try {
      const response = await client.post('/users/verify-otp/', {
        username,
        otp,
      });

      showToast('Vérification réussie ! Connexion en cours...', 'success');
      setStep(2);

      // Auto-login après 1.5 secondes
      await new Promise((resolve) => setTimeout(resolve, 1500));

      // Connexion automatique
      try {
        await login({ username, password: location.state?.password || '' });
        navigate('/citoyen/accueil', { replace: true });
      } catch {
        // Si auto-login échoue, rediriger vers login
        navigate('/login', { state: { tab: 'citoyen' }, replace: true });
      }
    } catch (err) {
      setError(err.response?.data?.detail || 'Code OTP invalide');
    } finally {
      setLoading(false);
    }
  };

  const handleResend = async () => {
    setError('');
    setLoading(true);
    try {
      await client.post('/users/resend-otp/', { username });
      showToast('Code OTP renvoyé', 'success');
      setResendTimer(60);

      // Countdown timer
      const interval = setInterval(() => {
        setResendTimer((prev) => {
          if (prev <= 1) {
            clearInterval(interval);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } catch (err) {
      setError(err.response?.data?.detail || 'Erreur lors de l\'envoi du code');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <button
          onClick={() => navigate('/signup')}
          className={`flex items-center gap-2 mb-8 ${darkMode ? 'text-navy-400 hover:text-navy-200' : 'text-navy-600 hover:text-navy-900'} transition`}
        >
          <ArrowLeft size={18} />
          Retour
        </button>

        <div className="text-center mb-8">
          <Logo size="lg" />
          <h1 className={`text-2xl font-bold mt-4 ${darkMode ? 'text-white' : 'text-navy-900'}`}>
            {step === 1 ? 'Vérifier votre identité' : 'Vérification réussie'}
          </h1>
        </div>

        {step === 1 ? (
          <form onSubmit={handleSubmitOTP} className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-950 border border-blue-200 dark:border-blue-800 rounded-lg p-4 mb-6">
              <div className="flex gap-2">
                <Clock size={20} className="text-blue-600 dark:text-blue-400 flex-shrink-0" />
                <div>
                  <p className={`text-sm font-medium ${darkMode ? 'text-blue-400' : 'text-blue-900'}`}>
                    Code OTP envoyé
                  </p>
                  <p className={`text-xs ${darkMode ? 'text-blue-300' : 'text-blue-700'} mt-1`}>
                    {email ? `Email: ${email}` : `Téléphone: ${phoneNumber}`}
                  </p>
                </div>
              </div>
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-2`}>
                Code OTP (6 chiffres minimum)
              </label>
              <input
                type="text"
                value={otp}
                onChange={(e) => {
                  setOtp(e.target.value);
                  setError('');
                }}
                placeholder="000000"
                maxLength="8"
                className={`w-full px-4 py-3 rounded-lg border text-center text-2xl tracking-widest font-mono ${
                  error
                    ? 'border-red-500'
                    : darkMode
                      ? 'border-navy-700 bg-navy-900 text-white'
                      : 'border-navy-200 bg-white'
                } focus:outline-none focus:ring-2 focus:ring-navy-500`}
              />
              {error && <p className="text-xs text-red-500 mt-2">{error}</p>}
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50"
            >
              {loading ? 'Vérification...' : 'Vérifier le code'}
            </button>

            <div className="text-center pt-4">
              <p className={`text-sm ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>
                Vous n'avez pas reçu le code ?
              </p>
              <button
                type="button"
                onClick={handleResend}
                disabled={resendTimer > 0 || loading}
                className={`text-sm font-semibold mt-2 ${
                  resendTimer > 0
                    ? `${darkMode ? 'text-navy-600' : 'text-navy-400'} cursor-not-allowed`
                    : `text-navy-600 dark:text-navy-400 hover:underline`
                }`}
              >
                {resendTimer > 0 ? `Renvoyer dans ${resendTimer}s` : 'Renvoyer le code'}
              </button>
            </div>
          </form>
        ) : (
          <div className="text-center py-8">
            <CheckCircle size={64} className="text-green-500 mx-auto mb-4" />
            <p className={`text-lg font-semibold ${darkMode ? 'text-white' : 'text-navy-900'} mb-2`}>
              Vérification réussie !
            </p>
            <p className={`text-sm ${darkMode ? 'text-navy-300' : 'text-navy-700'} mb-6`}>
              Vous pouvez maintenant accéder à votre compte citoyen.
            </p>
            <p className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>
              Redirection en cours vers le tableau de bord...
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Eye, EyeOff, Loader2 } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function SignupPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { darkMode } = useTheme();
  const { showToast } = useToast();

  const role = searchParams.get('role') || 'citoyen';
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [usernameOptions, setUsernameOptions] = useState([]);
  const [loadingUsernames, setLoadingUsernames] = useState(false);

  const [formData, setFormData] = useState({
    email: '',
    telephone: '',
    password: '',
    password_confirm: '',
    first_name: '',
    last_name: '',
    username: '',
  });

  // Générer automatiquement un username quand prénom/nom changent
  useEffect(() => {
    if (formData.first_name.trim() && formData.last_name.trim()) {
      const fetchUsernameOptions = async () => {
        setLoadingUsernames(true);
        try {
          const response = await client.get('/users/check-username/', {
            params: {
              first_name: formData.first_name,
              last_name: formData.last_name,
            },
          });
          setUsernameOptions(response.data.options || []);
          // Sélectionner la première option par défaut
          if (!formData.username && response.data.options?.length > 0) {
            setFormData((prev) => ({ ...prev, username: response.data.options[0] }));
          }
        } catch (error) {
          if (import.meta.env.DEV) console.error('Erreur lors du chargement des identifiants:', error);
          // Fallback: générer automatiquement un username basique
          const fallbackUsername = `${formData.first_name.toLowerCase().slice(0, 3)}${formData.last_name.toLowerCase().slice(0, 3)}`;
          setUsernameOptions([fallbackUsername]);
          if (!formData.username) {
            setFormData((prev) => ({ ...prev, username: fallbackUsername }));
          }
        } finally {
          setLoadingUsernames(false);
        }
      };
      fetchUsernameOptions();
    } else {
      setUsernameOptions([]);
      setFormData((prev) => ({ ...prev, username: '' }));
    }
  }, [formData.first_name, formData.last_name]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.first_name.trim()) newErrors.first_name = 'Prénom requis';
    if (!formData.last_name.trim()) newErrors.last_name = 'Nom requis';
    if (!formData.username) newErrors.username = 'Identifiant requis';

    // Pour les autorités, email est requis. Pour les citoyens, il est facultatif.
    if (role === 'autorite') {
      if (!formData.email.trim()) newErrors.email = 'Email requis';
      else if (!formData.email.includes('@')) newErrors.email = 'Email invalide';
    } else {
      // Citoyen: email facultatif
      if (formData.email.trim() && !formData.email.includes('@')) {
        newErrors.email = 'Email invalide';
      }
    }
    if (!formData.telephone.trim()) newErrors.telephone = 'Numéro de téléphone requis';
    if (!formData.password) newErrors.password = 'Mot de passe requis';
    if (formData.password.length < 8) newErrors.password = 'Min. 8 caractères';
    if (formData.password !== formData.password_confirm) {
      newErrors.password_confirm = 'Les mots de passe ne correspondent pas';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setLoading(true);
    try {
      const response = await client.post('/users/register/', {
        email: formData.email,
        password: formData.password,
        first_name: formData.first_name,
        last_name: formData.last_name,
        telephone: formData.telephone,
        username: formData.username,
        role: role,
      });

      showToast('Compte créé avec succès !', 'success');

      // Si c'est un compte citoyen, rediriger vers la vérification OTP
      if (response.data.requires_otp) {
        navigate('/otp-verify', {
          state: {
            username: formData.username,
            email: formData.email,
            phoneNumber: formData.telephone,
            password: formData.password,
          },
        });
      } else {
        // Sinon, rediriger vers login (pour les comptes autorité)
        navigate('/login');
      }
    } catch (error) {
      const errorData = error.response?.data || {};
      if (typeof errorData === 'object') {
        setErrors(errorData);
      } else {
        showToast(errorData.detail || 'Erreur lors de la création du compte', 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <Logo size="lg" />
          <p className={`text-sm ${darkMode ? 'text-navy-400' : 'text-navy-600'} mt-2`}>
            Créer un compte {role === 'autorite' ? 'd\'autorité' : 'citoyen'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <input type="text" name="first_name" value={formData.first_name} onChange={handleChange} placeholder="Prénom" className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`} />
              {errors.first_name && <p className="text-xs text-red-500">{errors.first_name}</p>}
            </div>
            <div>
              <input type="text" name="last_name" value={formData.last_name} onChange={handleChange} placeholder="Nom" className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`} />
              {errors.last_name && <p className="text-xs text-red-500">{errors.last_name}</p>}
            </div>
          </div>

          {usernameOptions.length > 0 && (
            <div className={`px-4 py-3 rounded-lg ${darkMode ? 'bg-navy-800 border border-navy-700' : 'bg-navy-50 border border-navy-200'}`}>
              <div className="flex items-center gap-2 mb-2">
                <p className={`text-xs font-medium ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>Choisissez votre identifiant</p>
                {loadingUsernames && <Loader2 size={12} className="animate-spin" />}
              </div>
              <div className="space-y-2">
                {usernameOptions.map((option) => (
                  <label key={option} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="username"
                      value={option}
                      checked={formData.username === option}
                      onChange={handleChange}
                      className="accent-red"
                    />
                    <code className={`font-mono text-sm font-semibold ${formData.username === option ? (darkMode ? 'text-white' : 'text-navy-900') : (darkMode ? 'text-navy-300' : 'text-navy-600')}`}>
                      {option}
                    </code>
                  </label>
                ))}
              </div>
            </div>
          )}
          {errors.username && <p className="text-xs text-red-500">{errors.username}</p>}

          <div>
            <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
              Email {role === 'autorite' ? <span className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-500'}`}>(Requis)</span> : <span className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-500'}`}>(Facultatif)</span>}
            </label>
            <input type="email" name="email" value={formData.email} onChange={handleChange} placeholder="email@exemple.com" className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`} />
            {errors.email && <p className="text-xs text-red-500">{errors.email}</p>}
          </div>

          <input type="tel" name="telephone" value={formData.telephone} onChange={handleChange} placeholder="+221 77 000 00 00" className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`} />
          {errors.telephone && <p className="text-xs text-red-500">{errors.telephone}</p>}

          <div className="relative">
            <input type={showPassword ? 'text' : 'password'} name="password" value={formData.password} onChange={handleChange} placeholder="Mot de passe (min. 8 caractères)" className={`w-full px-4 py-2 pr-10 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`} />
            <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-2.5"><Eye size={18} /></button>
          </div>
          {errors.password && <p className="text-xs text-red-500">{errors.password}</p>}

          <div className="relative">
            <input type={showConfirm ? 'text' : 'password'} name="password_confirm" value={formData.password_confirm} onChange={handleChange} placeholder="Confirmer le mot de passe" className={`w-full px-4 py-2 pr-10 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`} />
            <button type="button" onClick={() => setShowConfirm(!showConfirm)} className="absolute right-3 top-2.5"><EyeOff size={18} /></button>
          </div>
          {errors.password_confirm && <p className="text-xs text-red-500">{errors.password_confirm}</p>}

          <button type="submit" disabled={loading} className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50">
            {loading ? 'Création...' : 'Créer un compte'}
          </button>
        </form>

        <p className={`text-center text-sm mt-6 ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>
          Vous avez déjà un compte ? <button onClick={() => navigate('/login')} className="font-semibold text-red hover:underline transition">Se connecter</button>
        </p>
      </div>
    </div>
  );
}

import { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { obtainToken } from '../api/endpoints/auth';
import { decodeJwt } from './jwt';
import { getAccessToken, getRefreshToken, getUsername, setTokens, clearTokens } from './tokenStorage';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [accessToken, setAccessToken] = useState(null);
  const [role, setRole] = useState(null);
  const [username, setUsername] = useState(null);
  const [isReady, setIsReady] = useState(false);

  // Au montage : reprend la session depuis localStorage si un token y est
  // encore présent (évite de renvoyer vers /login à chaque rechargement).
  useEffect(() => {
    const token = getAccessToken();
    if (token) {
      const payload = decodeJwt(token);
      setAccessToken(token);
      setRole(payload?.role ?? null);
      setUsername(getUsername());
    }
    setIsReady(true);
  }, []);

  const login = useCallback(async ({ username, password }) => {
    const data = await obtainToken({ username, password });
    setTokens({ access: data.access, refresh: data.refresh, username });
    const payload = decodeJwt(data.access);
    setAccessToken(data.access);
    setRole(payload?.role ?? 'citoyen');
    setUsername(username);
    return payload?.role ?? 'citoyen';
  }, []);

  const logout = useCallback(() => {
    clearTokens();
    setAccessToken(null);
    setRole(null);
    setUsername(null);
  }, []);

  const value = {
    accessToken,
    role,
    username,
    isAuthenticated: !!accessToken,
    isReady,
    login,
    logout,
    // Exposé pour un éventuel appel manuel (ex: après une longue période
    // d'inactivité) — l'intercepteur axios gère déjà le cas 401 lui-même.
    refreshTokenValue: getRefreshToken,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth doit être utilisé à l’intérieur de <AuthProvider>.');
  return ctx;
}

import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from './AuthContext';

const AUTORITE_ROLES = ['autorite', 'admin', 'agent'];

export function homeRouteForRole(role) {
  return AUTORITE_ROLES.includes(role) ? '/autorite/dashboard' : '/citoyen/accueil';
}

/**
 * @param {'citoyen' | 'autorite'} space — quel espace cette branche de routes protège.
 */
export default function RequireAuth({ space, children }) {
  const { isAuthenticated, isReady, role } = useAuth();
  const location = useLocation();

  if (!isReady) return null; // évite un redirect prématuré le temps de relire localStorage

  if (!isAuthenticated) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  const isAutoriteRole = AUTORITE_ROLES.includes(role);
  const wrongSpace = (space === 'autorite' && !isAutoriteRole) || (space === 'citoyen' && isAutoriteRole);

  if (wrongSpace) {
    // Le rôle réel du compte (claim JWT) prime toujours sur l'URL demandée —
    // jamais d'écran d'erreur, on ramène simplement vers le bon espace.
    return <Navigate to={homeRouteForRole(role)} replace />;
  }

  return children;
}

/**
 * Décodage local d'un JWT (payload uniquement, pas de vérification de
 * signature côté client — l'application ne fait jamais confiance à ce
 * contenu pour appliquer un contrôle d'accès réel, seulement pour choisir
 * quel espace afficher. La sécurité réelle vient des permissions DRF
 * appliquées par le backend sur chaque endpoint.
 */
export function decodeJwt(token) {
  if (!token) return null;
  try {
    const payload = token.split('.')[1];
    const normalized = payload.replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
    const json = decodeURIComponent(
      atob(padded)
        .split('')
        .map((c) => '%' + c.charCodeAt(0).toString(16).padStart(2, '0'))
        .join('')
    );
    return JSON.parse(json);
  } catch {
    return null;
  }
}

export function isTokenExpired(token) {
  const payload = decodeJwt(token);
  if (!payload?.exp) return true;
  return Date.now() >= payload.exp * 1000;
}

// Stockage des JWT en localStorage. Le backend n'a pas de configuration
// CORS à cookies (CORS_ALLOWED_ORIGINS sans credentials), donc pas d'option
// "cookie httpOnly" possible sans changement backend — localStorage est le
// choix pragmatique pour une SPA qu'on rouvre depuis un écran d'accueil
// mobile sans redemander la connexion à chaque fois.
const ACCESS_KEY = 'mbeund_access_token';
const REFRESH_KEY = 'mbeund_refresh_token';
// Le JWT ne porte pas le username (seul `role` a été ajouté côté backend) —
// on le garde ici pour pouvoir l'afficher sur l'écran Profil après un
// rechargement de page, sans endpoint /me dédié.
const USERNAME_KEY = 'mbeund_username';

export function getAccessToken() {
  return localStorage.getItem(ACCESS_KEY);
}

export function getRefreshToken() {
  return localStorage.getItem(REFRESH_KEY);
}

export function getUsername() {
  return localStorage.getItem(USERNAME_KEY);
}

export function setTokens({ access, refresh, username }) {
  if (access) localStorage.setItem(ACCESS_KEY, access);
  if (refresh) localStorage.setItem(REFRESH_KEY, refresh);
  if (username) localStorage.setItem(USERNAME_KEY, username);
}

export function clearTokens() {
  localStorage.removeItem(ACCESS_KEY);
  localStorage.removeItem(REFRESH_KEY);
  localStorage.removeItem(USERNAME_KEY);
}

import { TrendingUp, AlertCircle, Save, Phone, Clock } from 'lucide-react';

/**
 * Baromètre IA prédictive pour estimer le risque d'inondation
 * basé sur les données météo actuelles.
 *
 * Règles IA:
 * - Précipitations: chaque 10mm augmente le risque de 25%
 * - Vitesse vent: chaque 10km/h augmente le risque de 10%
 * - Température: < 5°C réduit le risque de 20% (neige), > 30°C augmente légèrement
 */

function calculateRiskScore(previsions) {
  if (!previsions || previsions.length === 0) return 0;

  // Moyenne des données disponibles
  let totalPrecipitation = 0;
  let totalVent = 0;
  let avgTemp = 0;
  let count = 0;

  previsions.forEach((p) => {
    if (p.precipitation != null) totalPrecipitation += p.precipitation;
    if (p.vitesse_vent != null) totalVent += p.vitesse_vent;
    if (p.temperature != null) avgTemp += p.temperature;
    count++;
  });

  const avgPrecipitation = totalPrecipitation / (previsions.length || 1);
  const avgWindSpeed = totalVent / (previsions.length || 1);
  const avgTemperature = avgTemp / (count || 1);

  // Calcul du score de risque (0-100)
  let riskScore = 20; // Base risque

  // Précipitations (la plus importante)
  if (avgPrecipitation > 0) {
    riskScore += (avgPrecipitation / 10) * 25;
  }

  // Vitesse du vent
  if (avgWindSpeed > 0) {
    riskScore += (avgWindSpeed / 10) * 10;
  }

  // Température (considérations spéciales)
  if (avgTemperature < 5) {
    riskScore -= 20; // Froid = potentiellement neige, moins d'inondation
  } else if (avgTemperature > 30) {
    riskScore += 5; // Chaud + pluie = plus d'évaporation mais peut augmenter phénomènes extrêmes
  }

  return Math.min(100, Math.max(0, riskScore));
};

function getRiskLevel(score) {
  if (score < 25) return { level: 'vert', label: 'FAIBLE', color: 'bg-risk-vert text-white' };
  if (score < 50) return { level: 'jaune', label: 'MODÉRÉ', color: 'bg-risk-jaune text-navy-900' };
  if (score < 75) return { level: 'orange', label: 'ÉLEVÉ', color: 'bg-risk-orange text-white' };
  return { level: 'rouge', label: 'CRITIQUE', color: 'bg-red text-white' };
}

export default function BarometreIAPredictive({ previsions }) {
  const riskScore = calculateRiskScore(previsions);
  const riskInfo = getRiskLevel(riskScore);

  const predictions = [
    {
      metric: 'Précipitations',
      value: previsions?.length > 0 ? (previsions.reduce((sum, p) => sum + (p.precipitation || 0), 0) / previsions.length).toFixed(1) + ' mm' : '—',
      impact: 'Très influent',
    },
    {
      metric: 'Vitesse du vent',
      value: previsions?.length > 0 ? (previsions.reduce((sum, p) => sum + (p.vitesse_vent || 0), 0) / previsions.length).toFixed(1) + ' km/h' : '—',
      impact: 'Modéré',
    },
    {
      metric: 'Température',
      value: previsions?.length > 0 ? (previsions.reduce((sum, p) => sum + (p.temperature || 0), 0) / previsions.length).toFixed(1) + '°C' : '—',
      impact: 'Faible',
    },
  ];

  return (
    <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5 space-y-4">
      <div className="flex items-center gap-2 mb-1">
        <TrendingUp size={16} className="text-risk-orange" />
        <h3 className="text-base font-bold">Baromètre IA prédictive</h3>
      </div>
      <p className="text-xs text-navy-600 dark:text-navy-200">
        Prédiction intelligente du niveau de risque d'inondation basée sur la météo actuelle.
      </p>

      {/* Score principal */}
      <div className="flex items-center gap-4">
        <div className="flex-1">
          <div className="flex items-baseline gap-2 mb-2">
            <span className="text-3xl font-extrabold">{Math.round(riskScore)}</span>
            <span className="text-sm font-semibold text-navy-400">/100</span>
          </div>
          <div className="w-full bg-navy-100 dark:bg-navy-800 rounded-full h-3 overflow-hidden">
            <div
              className={`h-full transition-all ${riskInfo.color}`}
              style={{ width: `${riskScore}%` }}
            />
          </div>
        </div>

        <div className={`flex-shrink-0 px-4 py-3 rounded-lg ${riskInfo.color} text-center`}>
          <div className="text-2xl font-extrabold">{riskInfo.label}</div>
        </div>
      </div>

      {/* Détails des paramètres */}
      <div className="grid sm:grid-cols-3 gap-3 pt-3 border-t border-navy-100 dark:border-navy-800">
        {predictions.map((pred, idx) => (
          <div key={idx} className="text-center">
            <p className="text-xs font-semibold text-navy-400 mb-1">{pred.metric}</p>
            <p className="text-sm font-bold">{pred.value}</p>
            <p className="text-[11px] text-navy-500 mt-1">Impact: {pred.impact}</p>
          </div>
        ))}
      </div>

      {/* Recommandation */}
      <div className={`flex items-start gap-2.5 p-3 rounded-lg ${
        riskScore >= 75 ? 'bg-red/15' :
        riskScore >= 50 ? 'bg-risk-orange/15' :
        riskScore >= 25 ? 'bg-risk-jaune/15' :
        'bg-risk-vert/15'
      }`}>
        <AlertCircle size={14} className="flex-shrink-0 mt-0.5" />
        <p className="text-xs font-semibold">
          {riskScore >= 75 && "Risque critique : Préparez les mesures d'évacuation d'urgence"}
          {riskScore >= 50 && riskScore < 75 && "Risque élevé : Augmentez la vigilance et la préparation"}
          {riskScore >= 25 && riskScore < 50 && "Risque modéré : Maintenez une alerte active"}
          {riskScore < 25 && "Risque faible : Situation sous contrôle, continuez la surveillance"}
        </p>
      </div>
    </div>
  );
}

