              <p className="text-sm text-red-700 dark:text-red-300">{error}</p>
            </div>
          </div>
        </div>
      </AutoriteShell>
    );
  }

  if (!data || !data.statistiques) {
    return (
      <AutoriteShell>
        <div className="text-center text-navy-600 dark:text-navy-200">
          {data?.message || 'Aucune donnée disponible'}
