    borderRadius: 8,
    fontSize: 12,
    color: textColor,
  };

  if (loading) {
    return (
      <AutoriteShell>
        <div className="flex items-center justify-center min-h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-navy-500 mx-auto mb-4"></div>
            <p className="text-navy-600 dark:text-navy-200">Chargement des métriques...</p>
          </div>
        </div>
      </AutoriteShell>
    );
  }

  if (error) {
    return (
      <AutoriteShell>
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-6">
          <div className="flex items-center gap-3">
            <AlertCircle className="text-red-600 dark:text-red-400" size={20} />
            <div>
              <h3 className="font-bold text-red-900 dark:text-red-200">Erreur</h3>
              <p className="text-sm text-red-700 dark:text-red-300">{error}</p>
            </div>
          </div>
        </div>
      </AutoriteShell>
    );
  }

  if (!data || !data.metriques) {
    return (
      <AutoriteShell>
        <div className="text-center text-navy-600 dark:text-navy-200">
          Aucune donnée disponible
        </div>
      </AutoriteShell>
    );
  }

  const metriques = data.metriques;
  const matriceConfusion = data.matrice_confusion;
  const calibrationData = data.calibration_curve;

  // Préparer les données pour la courbe de calibration
  const calibrationChartData = calibrationData.avant_calibration.prob_pred.map((pred, i) => ({
    seuil: (i + 1) * 10,
    avant: calibrationData.avant_calibration.prob_true[i],
    apres: calibrationData.apres_calibration.prob_true[i],
    expected: calibrationData.avant_calibration.prob_pred[i],
  }));

  // Préparer les données pour la matrice de confusion
  const matrixChartData = [
    { risque: 'Vert', vert: matriceConfusion.vert.vert, jaune: matriceConfusion.vert.jaune, orange: matriceConfusion.vert.orange, rouge: matriceConfusion.vert.rouge },
    { risque: 'Jaune', vert: matriceConfusion.jaune.vert, jaune: matriceConfusion.jaune.jaune, orange: matriceConfusion.jaune.orange, rouge: matriceConfusion.jaune.rouge },
    { risque: 'Orange', vert: matriceConfusion.orange.vert, jaune: matriceConfusion.orange.jaune, orange: matriceConfusion.orange.orange, rouge: matriceConfusion.orange.rouge },
    { risque: 'Rouge', vert: matriceConfusion.rouge.vert, jaune: matriceConfusion.rouge.jaune, orange: matriceConfusion.rouge.orange, rouge: matriceConfusion.rouge.rouge },
  ];

  const improvementPercent = metriques.brier_improvement_percent;
  const accuracyGain = (metriques.accuracy_apres_percent - metriques.accuracy_avant_percent).toFixed(1);

  return (
    <AutoriteShell>
      <div>
        <h1 className="text-3xl font-extrabold">Fiabilité du Modèle</h1>
        <p className="text-base text-navy-600 dark:text-navy-200 mt-0.5">
          Analyse de la précision et calibration du modèle Random Forest
        </p>
      </div>

      {/* Métriques clés */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
          <p className={`text-xs font-medium ${textMuted}`}>Accuracy (après calibration)</p>
          <p className="text-2xl font-bold text-navy-900 dark:text-white mt-2">{metriques.accuracy_apres_percent.toFixed(1)}%</p>
          <p className={`text-xs mt-1 ${accuracyGain >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
            {accuracyGain >= 0 ? '+' : ''}{accuracyGain}% vs avant
          </p>
        </div>

        <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
          <p className={`text-xs font-medium ${textMuted}`}>Brier Score (amélioration)</p>
          <p className="text-2xl font-bold text-green-600 dark:text-green-400 mt-2">{improvementPercent.toFixed(1)}%</p>
          <p className={`text-xs mt-1 ${textMuted}`}>{metriques.brier_score_avant.toFixed(4)} → {metriques.brier_score_apres.toFixed(4)}</p>
        </div>

        <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
          <p className={`text-xs font-medium ${textMuted}`}>Log Loss (après)</p>
          <p className="text-2xl font-bold text-navy-900 dark:text-white mt-2">{metriques.log_loss_apres.toFixed(4)}</p>
          <p className={`text-xs mt-1 ${textMuted}`}>{metriques.log_loss_avant.toFixed(4)} avant</p>
        </div>

        <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
          <p className={`text-xs font-medium ${textMuted}`}>Échantillons de test</p>
          <p className="text-2xl font-bold text-navy-900 dark:text-white mt-2">{data.nombre_echantillons_test}</p>
          <p className={`text-xs mt-1 ${textMuted}`}>jours évalués</p>
        </div>
      </div>

      {/* Graphiques */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Courbe de calibration */}
        <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
          <h3 className="text-base font-bold mb-4 flex items-center gap-2">
            <TrendingUp size={15} />
            Courbe de calibration (Risque Rouge)
          </h3>
          <p className={`text-xs ${textMuted} mb-4`}>Avant vs après calibration. La diagonale grise = parfaite calibration.</p>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={calibrationChartData} margin={{ top: 5, right: 10, left: -15, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                <XAxis dataKey="seuil" stroke={axisColor} fontSize={11} fill={axisColor} label={{ value: 'Probabilité prédite (%)', position: 'insideBottomRight', offset: -5, fill: axisColor }} />
                <YAxis stroke={axisColor} fontSize={11} fill={axisColor} label={{ value: 'Prob. réelle (%)', angle: -90, position: 'insideLeft', fill: axisColor }} domain={[0, 1]} />
                <Tooltip contentStyle={tooltipStyle} formatter={(v) => (v * 100).toFixed(1) + '%'} />
                <Legend />
                <Line type="monotone" dataKey="avant" stroke="#EF6234" name="Avant calibration" dot={{ r: 4 }} />
                <Line type="monotone" dataKey="apres" stroke="#10B981" name="Après calibration" dot={{ r: 4 }} />
                <Line type="linear" dataKey="expected" stroke="#CCCCCC" name="Idéal" strokeDasharray="5 5" dot={false} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Matrice de confusion */}
        <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
          <h3 className="text-base font-bold mb-4 flex items-center gap-2">
            <BarChart3 size={15} />
            Matrice de confusion (Prédictions correctes par classe)
          </h3>
          <div className="h-64 overflow-x-auto">
            <ResponsiveContainer width={400} height={256}>
              <BarChart data={matrixChartData} margin={{ top: 5, right: 10, left: 60, bottom: 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                <XAxis dataKey="risque" stroke={axisColor} fontSize={11} fill={axisColor} />
                <YAxis stroke={axisColor} fontSize={11} fill={axisColor} />
                <Tooltip contentStyle={tooltipStyle} />
                <Legend />
                <Bar dataKey="vert" name="Vert" fill={RISK_COLORS.vert} />
                <Bar dataKey="jaune" name="Jaune" fill={RISK_COLORS.jaune} />
                <Bar dataKey="orange" name="Orange" fill={RISK_COLORS.orange} />
                <Bar dataKey="rouge" name="Rouge" fill={RISK_COLORS.rouge} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Interprétation */}
      <div className={`rounded-xl p-5 border ${darkMode ? 'bg-navy-800 border-navy-700' : 'bg-white border-navy-50'}`}>
        <div className="flex items-start gap-3">
          <CheckCircle className="text-green-600 dark:text-green-400 flex-shrink-0 mt-1" size={20} />
          <div>
            <h3 className="font-bold text-navy-900 dark:text-white mb-2">Interprétation</h3>
            <ul className={`text-sm space-y-2 ${textMuted}`}>
              <li>
                <strong>Brier Score :</strong> Mesure l'écart moyen entre les probabilités prédites et les vrais labels. Une amélioration de {improvementPercent.toFixed(1)}% confirme que la calibration rend les probabilités plus fiables.
              </li>
              <li>
                <strong>Accuracy :</strong> Le modèle prédit correctement le niveau de risque dans {metriques.accuracy_apres_percent.toFixed(1)}% des cas (après calibration).
              </li>
              <li>
                <strong>Courbe de calibration :</strong> Plus elle s'aligne avec la diagonale grise, plus les probabilités prédites correspondent à la réalité. Le modèle calibré est plus proche de l'idéal.
              </li>
              <li>
                <strong>Matrice de confusion :</strong> Montre quels risques sont bien classés (diagonale) et lesquels sont confondus. Les valeurs élevées en diagonale indiquent une bonne classification.
              </li>
            </ul>
          </div>
        </div>
      </div>

      {/* Métadonnées */}
      <div className={`rounded-xl p-4 text-xs ${textMuted}`}>
        <p>
          Données extraites le {new Date().toLocaleDateString('fr-FR')}. Modèle : Random Forest ({data.nombre_echantillons_test} échantillons de test).
        </p>
      </div>
    </AutoriteShell>
  );
}

import { useState, useEffect } from 'react';
import { Send, CheckCircle2, ChevronLeft, ChevronRight, Plus, AlertTriangle, Droplet, CornerDownRight, Check, Phone, Clock, Save, X } from 'lucide-react';
import AutoriteShell from '../desktop/AutoriteShell';
import RiskBadge from '../../shared/components/RiskBadge';
import A11yStatusMessage from '../../shared/components/A11yStatusMessage';
import ErrorMessage from '../../shared/components/ErrorMessage';
import { useZones } from '../../shared/hooks/useZones';
import { useAlertesListe, useCreateAlerte, useUpdateAlerteStatut } from '../../shared/hooks/useAlertes';
import { useEnregistrerTriageAppel } from '../../shared/hooks/useEnregistrerTriageAppel';
import { flattenApiErrors } from '../../shared/utils/apiErrors';

const NIVEAUX = [
  { value: 'vert', label: 'Vert' },
  { value: 'jaune', label: 'Jaune' },
  { value: 'orange', label: 'Orange' },
  { value: 'rouge', label: 'Rouge' },
];

const STATUT_LABELS = {
  en_attente: 'En attente',
  envoyee: 'Envoyée',
  resolue: 'Résolue',
};

// Machine à états exacte de l'action `statut` côté backend
// (AlerteViewSet.statut) : en_attente -> envoyee -> resolue, jamais en arrière.
const NEXT_STATUT = { en_attente: 'envoyee', envoyee: 'resolue' };
const NEXT_LABEL = { en_attente: 'Envoyer', envoyee: 'Marquer résolue' };

function formatDateTime(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString('fr-FR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
}

function NouvelleAlerteForm() {
  const { data: zonesData } = useZones();
  const zones = zonesData?.features?.map((f) => ({ id: f.id, ...f.properties })) ?? [];

  const [zoneId, setZoneId] = useState('');
  const [niveau, setNiveau] = useState('jaune');
  const [message, setMessage] = useState('');
  const [canaux, setCanaux] = useState('sms,push');

  const mutation = useCreateAlerte();

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!zoneId) return;
    mutation.mutate(
      {
        zone: Number(zoneId),
        niveau,
        message,
        canaux,
        timestamp: new Date().toISOString(),
      },
      {
        onSuccess: () => {
          setMessage('');
        },
      }
    );
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5 flex flex-col gap-3">
      <h3 className="text-base font-bold flex items-center gap-2">
        <Plus size={15} />
        Émettre une nouvelle alerte
      </h3>

      <div className="grid sm:grid-cols-2 gap-3">
        <label className="block">
          <span className="block text-sm font-semibold mb-1.5" id="zone-label">Zone</span>
          <span className="block text-xs text-navy-500 dark:text-navy-400 mb-1.5" id="zone-desc">
            Sélectionner la zone affectée
          </span>
          <select
            required
            value={zoneId}
            onChange={(e) => setZoneId(e.target.value)}
            aria-labelledby="zone-label"
            aria-describedby="zone-desc"
            aria-invalid={!zoneId && mutation.isError}
            className="w-full px-3 py-2.5 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-base"
          >
            <option value="">Sélectionner…</option>
            {zones.map((z) => (
              <option key={z.id} value={z.id}>
                {z.quartier}
              </option>
            ))}
          </select>
        </label>

        <label className="block">
          <span className="block text-sm font-semibold mb-1.5" id="niveau-label">Niveau</span>
          <span className="block text-xs text-navy-500 dark:text-navy-400 mb-1.5" id="niveau-desc">
            Vert (faible) à Rouge (critique)
          </span>
          <select
            value={niveau}
            onChange={(e) => setNiveau(e.target.value)}
            aria-labelledby="niveau-label"
            aria-describedby="niveau-desc"
            className="w-full px-3 py-2.5 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-base"
          >
            {NIVEAUX.map((n) => (
              <option key={n.value} value={n.value}>
                {n.label}
              </option>
            ))}
          </select>
        </label>
      </div>

      <label className="block">
        <span className="block text-sm font-semibold mb-1.5" id="message-label">Message</span>
        <span className="block text-xs text-navy-500 dark:text-navy-400 mb-1.5" id="message-desc">
          Décrivez la situation et les actions recommandées
        </span>
        <textarea
          rows={2}
          required
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Ex : Montée d'eau rapide signalée, niveau rouge."
          aria-labelledby="message-label"
          aria-describedby="message-desc"
          aria-invalid={!message && mutation.isError}
          className="w-full px-3 py-2.5 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-base"
        />
      </label>

      <label className="block">
        <span className="block text-sm font-semibold mb-1.5" id="canaux-label">Canaux</span>
        <span className="block text-xs text-navy-500 dark:text-navy-400 mb-1.5" id="canaux-desc">
          Canaux de communication (sms, push, etc)
        </span>
        <input
          type="text"
          value={canaux}
          onChange={(e) => setCanaux(e.target.value)}
          placeholder="sms,push"
          aria-labelledby="canaux-label"
          aria-describedby="canaux-desc"
          className="w-full px-3 py-2.5 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-base"
        />
      </label>

      {mutation.isError && (
        <ErrorMessage
          error={flattenApiErrors(mutation.error)[0]}
          title="Impossible de créer l'alerte"
          suggestion="Vérifiez les champs et réessayez"
          type="error"
        />
      )}

      {mutation.isSuccess && (
        <A11yStatusMessage
          type="success"
          message="✓ Alerte créée et envoyée avec succès!"
          visible={true}
        />
      )}

      <button
        type="submit"
        disabled={mutation.isPending}
        aria-label="Émettre l'alerte aux citoyens"
        aria-busy={mutation.isPending}
        className="self-start flex items-center gap-2 bg-red text-white font-bold text-sm px-4 py-2.5 rounded-md disabled:opacity-60 hover:bg-red-700 transition-colors"
      >
        <Send size={14} aria-hidden="true" />
        {mutation.isPending ? 'Envoi…' : "Émettre l'alerte"}
      </button>
    </form>
  );
}

function FilDeReflexe() {
  const categories = [
    {
      id: 'electrique',
      titre: '⚡ Danger électronique',
      icon: AlertTriangle,
      actions: [
        'Couper l\'électricité dans les zones inondées',
        'Signaler les câbles électriques endommagés',
        'Évacuer les installations électriques critiques',
        'Informer les citoyens des dangers',
        'Demander intervention électriciens urgents',
      ],
    },
    {
      id: 'eau',
      titre: '💧 Eau potable & désinfectée',
      icon: Droplet,
      actions: [
        'Vérifier la qualité de l\'eau avec tests',
        'Distribuer de l\'eau potable aux citoyens',
        'Recommander de bouillir l\'eau contaminée',
        'Fermer les points d\'approvisionnement suspects',
        'Mettre en place des stations de désinfection',
      ],
    },
    {
      id: 'evacuation',
      titre: '🚨 Évacuation réflexe & secours',
      icon: CornerDownRight,
      actions: [
        'Identifier les zones à évacuer immédiatement',
        'Activer les relais de quartier et la communication',
        'Accueillir les évacués aux points de refuge',
        'Organiser les secours médicaux et alimentaires',
        'Maintenir contact radio avec équipes terrain',
      ],
    },
  ];

  const [expandedCategory, setExpandedCategory] = useState(null);
  const [checkedItems, setCheckedItems] = useState({});
  const [notes, setNotes] = useState({});
  const [callStartTime] = useState(new Date());
  const [callMinutes, setCallMinutes] = useState(0);
  const [citoyenInput, setCitoyenInput] = useState('');
  const [statusMessage, setStatusMessage] = useState('');
  const mutation = useEnregistrerTriageAppel();

  // Simulate call timer
  useEffect(() => {
    const timer = setInterval(() => {
      const elapsed = Math.floor((new Date() - callStartTime) / 60000);
      setCallMinutes(elapsed);
    }, 1000);
    return () => clearInterval(timer);
  }, [callStartTime]);

  const toggleItem = (catId, idx) => {
    const key = `${catId}-${idx}`;
    setCheckedItems((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const getTotalProgress = () => {
    const total = categories.reduce((sum, cat) => sum + cat.actions.length, 0);
    const completed = Object.values(checkedItems).filter(Boolean).length;
    return Math.round((completed / total) * 100);
  };

  const handleSaveCall = () => {
    if (!citoyenInput.trim()) {
      setStatusMessage('Veuillez entrer un ID ou un numéro de citoyen.');
      setTimeout(() => setStatusMessage(''), 5000);
      return;
    }

    // Find first category with checked items
    let categorie = null;
    for (let cat of categories) {
      const hasCategoryItems = cat.actions.some((_, idx) => checkedItems[`${cat.id}-${idx}`]);
      if (hasCategoryItems) {
        categorie = cat.id;
        break;
      }
    }

    if (!categorie) {
      setStatusMessage('Veuillez cocher au moins un élément.');
      setTimeout(() => setStatusMessage(''), 5000);
      return;
    }

    // Prepare triage data
    const isNumeric = /^\d+$/.test(citoyenInput.trim());
    const triageData = {
      citoyen_id: isNumeric ? Number(citoyenInput.trim()) : null,
      numero_citoyen: !isNumeric ? citoyenInput.trim() : null,
      categorie,
      duree_appel_minutes: callMinutes,
      reponses: checkedItems,
      pourcentage_complete: getTotalProgress(),
      notes_generales: Object.entries(notes)
        .filter(([, val]) => val)
        .map(([key, val]) => `${key}: ${val}`)
        .join('\n'),
    };

    mutation.mutate(triageData, {
      onSuccess: () => {
        setStatusMessage('✓ Triage d\'appel enregistré avec succès!');
        setCitoyenInput('');
        setCheckedItems({});
        setNotes({});
        setTimeout(() => setStatusMessage(''), 5000);
      },
      onError: (error) => {
        const errors = flattenApiErrors(error);
        setStatusMessage(`✗ Erreur: ${errors[0] || 'Impossible d\'enregistrer le triage'}`);
        setTimeout(() => setStatusMessage(''), 5000);
      },
    });
  };

  return (
    <div className="space-y-4">
      {/* Header avec timer et progress */}
      <div className="bg-gradient-to-r from-navy-50 to-navy-100 dark:from-navy-900 dark:to-navy-800 rounded-xl p-4 border border-navy-100 dark:border-navy-700 space-y-3">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div className="flex items-center gap-3">
            <Phone size={16} className="text-red" />
            <div>
              <p className="text-xs font-semibold text-navy-400">Appel en cours</p>
              <p className="text-sm font-bold flex items-center gap-1.5">
                <Clock size={14} />
                {callMinutes} min
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div>
              <p className="text-xs font-semibold text-navy-400 text-right">Complétude du triage</p>
              <p className="text-sm font-bold text-red">{getTotalProgress()}%</p>
            </div>
            <div className="w-24 bg-navy-200 dark:bg-navy-700 rounded-full h-2.5">
              <div
                className="h-full bg-red rounded-full transition-all"
                style={{ width: `${getTotalProgress()}%` }}
              />
            </div>
          </div>

          <button
            onClick={handleSaveCall}
            disabled={mutation.isPending}
            aria-label="Enregistrer l'appel de triage avec toutes les données saisies"
            aria-busy={mutation.isPending}
            className="flex items-center gap-1.5 bg-red text-white font-bold text-sm px-3.5 py-2 rounded-md hover:bg-red-600 transition flex-shrink-0 disabled:opacity-60"
          >
            <Save size={14} aria-hidden="true" />
            {mutation.isPending ? 'Enregistrement…' : 'Enregistrer appel'}
          </button>
        </div>

        {/* Citoyen input + status */}
        <div className="flex items-end gap-3 flex-wrap">
          <label className="block flex-1 min-w-[200px]">
            <span className="block text-xs font-semibold text-navy-500 mb-1.5" id="citoyen-label">
              ID ou numéro citoyen
            </span>
            <span className="block text-xs text-navy-400 mb-1" id="citoyen-desc">
              Entrez l'ID (ex: 123) ou le numéro de téléphone
            </span>
            <input
              type="text"
              placeholder="Ex: 123 ou +221 77 123 45 67"
              value={citoyenInput}
              onChange={(e) => setCitoyenInput(e.target.value)}
              aria-labelledby="citoyen-label"
              aria-describedby="citoyen-desc"
              aria-invalid={statusMessage.includes('Veuillez entrer')}
              className="w-full px-3 py-2 rounded border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy text-sm"
            />
          </label>

          {statusMessage && (
            <div
              role="status"
              aria-live="polite"
              aria-atomic="true"
              className={`flex items-center gap-2 text-xs font-semibold px-3 py-2 rounded flex-1 min-w-[200px] ${
                statusMessage.startsWith('✗') ? 'bg-red/10 text-red' : 'bg-green/10 text-green-600'
              }`}
            >
              <span>{statusMessage}</span>
            </div>
          )}
        </div>
      </div>

      {/* Catégories */}
      <div className="grid sm:grid-cols-1 lg:grid-cols-3 gap-4">
        {categories.map((cat) => {
          const Icon = cat.icon;
          const isExpanded = expandedCategory === cat.id;
          const categoryCompleted = cat.actions.filter(
            (_, idx) => checkedItems[`${cat.id}-${idx}`]
          ).length;

          return (
            <div
              key={cat.id}
              className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl overflow-hidden"
            >
              <button
                onClick={() => setExpandedCategory(isExpanded ? null : cat.id)}
                aria-expanded={isExpanded}
                aria-controls={`category-${cat.id}`}
                aria-label={`${cat.titre} - ${categoryCompleted} sur ${cat.actions.length} complétés`}
                className="w-full px-5 py-3 flex items-center gap-3 bg-navy-50 dark:bg-navy-900 hover:bg-navy-100 dark:hover:bg-navy-800 transition text-left focus:outline-none focus:ring-2 focus:ring-red focus:ring-inset"
              >
                <Icon size={18} className="text-red flex-shrink-0" aria-hidden="true" />
                <div className="flex-1 min-w-0">
                  <h4 className="font-bold text-sm">{cat.titre}</h4>
                  <p className="text-xs text-navy-400 mt-0.5">{categoryCompleted}/{cat.actions.length} complétés</p>
                </div>
                <span className={`transform transition flex-shrink-0 ${isExpanded ? 'rotate-180' : ''}`} aria-hidden="true">▼</span>
              </button>

              {isExpanded && (
                <div id={`category-${cat.id}`} className="p-4 space-y-3 border-t border-navy-50 dark:border-navy-700">
                  {cat.actions.map((action, idx) => {
                    const key = `${cat.id}-${idx}`;
                    const isChecked = checkedItems[key];
                    const checkboxId = `checkbox-${key}`;
                    const notesId = `notes-${key}`;

                    return (
                      <div key={idx} className="space-y-2">
                        <label htmlFor={checkboxId} className="flex items-start gap-2.5 cursor-pointer">
                          <input
                            id={checkboxId}
                            type="checkbox"
                            checked={isChecked || false}
                            onChange={() => toggleItem(cat.id, idx)}
                            aria-describedby={notesId}
                            className="w-4 h-4 accent-red flex-shrink-0 mt-0.5 cursor-pointer focus:ring-2 focus:ring-red focus:ring-inset"
                          />
                          <span className={`text-sm transition ${isChecked ? 'line-through text-navy-400' : 'text-navy-600 dark:text-navy-200 font-semibold'}`}>
                            {action}
                          </span>
                        </label>
                        {isChecked && (
                          <textarea
                            id={notesId}
                            placeholder="Ajouter des notes (optionnel)..."
                            aria-label={`Notes pour ${action}`}
                            value={notes[key] || ''}
                            onChange={(e) => setNotes((prev) => ({ ...prev, [key]: e.target.value }))}
                            rows={2}
                            className="ml-6 w-full px-2.5 py-1.5 text-xs rounded border border-navy-100 dark:border-navy-700 bg-navy-50 dark:bg-navy-900 text-navy-600 dark:text-navy-200 placeholder:text-navy-400 focus:ring-2 focus:ring-red focus:ring-inset"
                          />
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function AlerteRow({ alerte }) {
  const mutation = useUpdateAlerteStatut();
  const next = NEXT_STATUT[alerte.statut];

  return (
    <div className="flex items-start gap-3 p-4 border border-navy-50 dark:border-navy-800 rounded-lg">
      <RiskBadge niveau={alerte.niveau} className="mt-0.5 flex-shrink-0" />
      <div className="min-w-0 flex-1">
        <div className="flex items-center justify-between gap-2">
          <span className="text-base font-semibold truncate">{alerte.zone?.quartier}</span>
          <span className="text-xs text-navy-400 flex-shrink-0">{formatDateTime(alerte.timestamp)}</span>
        </div>
        <p className="text-sm text-navy-600 dark:text-navy-200 mt-0.5">{alerte.message}</p>
        <div className="flex items-center gap-3 mt-2">
          <span className="text-[11px] font-bold uppercase text-navy-400">{STATUT_LABELS[alerte.statut] ?? alerte.statut}</span>
          {next && (
            <button
              onClick={() => mutation.mutate({ id: alerte.id, statut: next })}
              disabled={mutation.isPending}
              className="flex items-center gap-1.5 text-sm font-bold text-red disabled:opacity-60"
            >
              <CheckCircle2 size={13} />
              {NEXT_LABEL[alerte.statut]}
            </button>
          )}
        </div>
        {mutation.isError && (
          <p className="text-xs text-red mt-1">{flattenApiErrors(mutation.error)[0]}</p>
        )}
      </div>
    </div>
  );
}

export default function GestionDeCrisePage() {
  const [page, setPage] = useState(1);
  const { data, isLoading } = useAlertesListe(page);
  const alertes = data?.results ?? [];

  return (
    <AutoriteShell>
      <div>
        <h1 className="text-3xl font-extrabold">Gestion de crise</h1>
        <p className="text-base text-navy-600 dark:text-navy-200 mt-0.5">
          Cycle de vie des alertes · en attente → envoyée → résolue
        </p>
      </div>

      <NouvelleAlerteForm />

      <div>
        <h3 className="text-lg font-bold mb-4">📋 Fil de réflexe — Réponse rapide en 3 catégories</h3>
        <FilDeReflexe />
      </div>

      <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5 flex flex-col gap-3">
        <h3 className="text-base font-bold">Toutes les alertes · {data?.count ?? 0}</h3>
        {isLoading ? (
          <p className="text-sm text-navy-400">Chargement…</p>
        ) : alertes.length === 0 ? (
          <p className="text-sm text-navy-400">Aucune alerte pour l’instant.</p>
        ) : (
          alertes.map((a) => <AlerteRow key={a.id} alerte={a} />)
        )}
      </div>

      {(data?.next || data?.previous) && (
        <div className="flex items-center justify-center gap-3">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={!data?.previous}
            className="flex items-center gap-1 text-sm font-bold text-navy-600 dark:text-navy-200 disabled:opacity-40"
          >
            <ChevronLeft size={14} />
            Précédent
          </button>
          <span className="text-sm text-navy-400">Page {page}</span>
          <button
            onClick={() => setPage((p) => p + 1)}
            disabled={!data?.next}
            className="flex items-center gap-1 text-sm font-bold text-navy-600 dark:text-navy-200 disabled:opacity-40"
          >
            Suivant
            <ChevronRight size={14} />
          </button>
        </div>
      )}
    </AutoriteShell>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Eye, EyeOff, Copy, Check, Lock, Trash2, RefreshCw, Search, Loader2 } from 'lucide-react';
import AutoriteShell from '../desktop/AutoriteShell';
import { useTheme } from '../../theme/ThemeContext';
import { useAuth } from '../../auth/AuthContext';
import client from '../../api/client';
import { useToast } from '../../shared/toast/ToastContext';

function ManageAuthoritiesPageContent() {
  const { darkMode } = useTheme();
  const { showToast } = useToast();
  const { role } = useAuth();
  const navigate = useNavigate();

  // Vérifier que l'utilisateur est admin
  if (role !== 'admin') {
    return (
      <div className="space-y-6">
        <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-12 text-center">
          <Lock size={48} className="mx-auto mb-4 text-red-500" />
          <h2 className="text-2xl font-bold text-navy dark:text-white mb-2">Accès réservé</h2>
          <p className="text-navy-600 dark:text-navy-300 mb-6">
            Cette page est réservée aux administrateurs.
          </p>
          <button
            onClick={() => navigate('/autorite/dashboard')}
            className="bg-navy dark:bg-navy-800 text-white px-6 py-2 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-700 transition"
          >
            Retour au dashboard
          </button>
        </div>
      </div>
    );
  }

  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [authorities, setAuthorities] = useState([]);
  const [visiblePasswords, setVisiblePasswords] = useState({});
  const [copiedField, setCopiedField] = useState(null);
  const [deleteModal, setDeleteModal] = useState(null);
  const [regenerateConfirmModal, setRegenerateConfirmModal] = useState(null);
  const [regenerateResultModal, setRegenerateResultModal] = useState(null);
  const [newPassword, setNewPassword] = useState(null);
  const [creationResultModal, setCreationResultModal] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [usernameOptions, setUsernameOptions] = useState([]);
  const [loadingUsernames, setLoadingUsernames] = useState(false);

  // Filtrer les autorités selon la recherche
  const filteredAuthorities = authorities.filter((auth) => {
    const query = searchQuery.toLowerCase();
    return (
      auth.first_name.toLowerCase().includes(query) ||
      auth.last_name.toLowerCase().includes(query) ||
      auth.username.toLowerCase().includes(query) ||
      (auth.email && auth.email.toLowerCase().includes(query))
    );
  });

  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    email: '',
    telephone: '',
    username: '',
  });

  // Charger les options d'identifiant quand prénom/nom changent
  useEffect(() => {
    if (formData.first_name.trim() && formData.last_name.trim()) {
      const fetchUsernameOptions = async () => {
        setLoadingUsernames(true);
        try {
          const response = await client.get('/users/check-username/', {
            params: {
              first_name: formData.first_name,
              last_name: formData.last_name,
            },
          });
          setUsernameOptions(response.data.options || []);
          // Sélectionner la première option par défaut
          if (!formData.username && response.data.options?.length > 0) {
            setFormData((prev) => ({ ...prev, username: response.data.options[0] }));
          }
        } catch (error) {
          if (import.meta.env.DEV) console.error('Erreur lors du chargement des identifiants:', error);
        } finally {
          setLoadingUsernames(false);
        }
      };
      fetchUsernameOptions();
    } else {
      setUsernameOptions([]);
      setFormData((prev) => ({ ...prev, username: '' }));
    }
  }, [formData.first_name, formData.last_name]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.first_name.trim()) newErrors.first_name = 'Prénom requis';
    if (!formData.last_name.trim()) newErrors.last_name = 'Nom requis';
    if (!formData.username) newErrors.username = 'Identifiant requis';
    if (!formData.email.trim()) newErrors.email = 'Email requis';
    else if (!formData.email.includes('@')) newErrors.email = 'Email invalide';
    if (!formData.telephone.trim()) newErrors.telephone = 'Numéro de téléphone requis';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setLoading(true);
    try {
      const response = await client.post('/users/create-authority/', {
        first_name: formData.first_name,
        last_name: formData.last_name,
        email: formData.email,
        telephone: formData.telephone,
        username: formData.username,
      });

      setAuthorities([...authorities, response.data]);
      setCreationResultModal(response.data);
      setFormData({ first_name: '', last_name: '', email: '', telephone: '', username: '' });
      setUsernameOptions([]);
      showToast('Autorité créée avec succès !', 'success');
    } catch (error) {
      const errorData = error.response?.data || {};
      if (typeof errorData === 'object') {
        setErrors(errorData);
      } else {
        showToast(errorData.detail || 'Erreur lors de la création', 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text, field) => {
    navigator.clipboard.writeText(text);
    setCopiedField(field);
    setTimeout(() => setCopiedField(null), 2000);
  };

  const togglePasswordVisibility = (id) => {
    setVisiblePasswords((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const handleConfirmRegenerate = async () => {
    try {
      const response = await client.post('/users/regenerate-authority-password/', { username: regenerateConfirmModal });
      setNewPassword(response.data);
      setRegenerateConfirmModal(null);
      setRegenerateResultModal(response.data.username);
      showToast('Mot de passe régénéré avec succès !', 'success');
    } catch (error) {
      showToast('Erreur lors de la régénération du mot de passe', 'error');
      setRegenerateConfirmModal(null);
    }
  };

  const handleDeleteAuthority = async (username) => {
    try {
      await client.post('/users/delete-authority/', { username });
      setAuthorities(authorities.filter((a) => a.username !== username));
      setDeleteModal(null);
      showToast('Autorité supprimée avec succès !', 'success');
    } catch (error) {
      showToast('Erreur lors de la suppression', 'error');
    }
  };

  // Charger les autorités créées aujourd'hui au montage
  useEffect(() => {
    const loadAuthorities = async () => {
      try {
        const response = await client.get('/users/list-authorities/');
        setAuthorities(response.data.authorities || []);
      } catch (error) {
        if (import.meta.env.DEV) console.error('Erreur lors du chargement des autorités:', error);
      }
    };
    loadAuthorities();
  }, []);

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-navy dark:text-white">Gérer les autorités</h1>
        <p className="text-sm text-navy-600 dark:text-navy-200 mt-0.5">Créez des comptes autorité. Les identifiants seront générés automatiquement.</p>
      </div>

      <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-6">
        <h2 className="text-lg font-bold text-navy dark:text-white mb-4">Créer une nouvelle autorité</h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-navy-700 dark:text-navy-200 mb-1">Prénom</label>
              <input
                type="text"
                name="first_name"
                value={formData.first_name}
                onChange={handleChange}
                placeholder="Jean"
                className="w-full px-4 py-2 rounded-lg border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy-800 text-navy dark:text-white"
              />
              {errors.first_name && <p className="text-xs text-red-500 mt-1">{errors.first_name}</p>}
            </div>
            <div>
              <label className="block text-sm font-medium text-navy-700 dark:text-navy-200 mb-1">Nom</label>
              <input
                type="text"
                name="last_name"
                value={formData.last_name}
                onChange={handleChange}
                placeholder="Dupont"
                className="w-full px-4 py-2 rounded-lg border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy-800 text-navy dark:text-white"
              />
              {errors.last_name && <p className="text-xs text-red-500 mt-1">{errors.last_name}</p>}
            </div>
          </div>

          {usernameOptions.length > 0 && (
            <div className={`px-4 py-3 rounded-lg ${darkMode ? 'bg-navy-800 border border-navy-700' : 'bg-navy-50 border border-navy-200'}`}>
              <div className="flex items-center gap-2 mb-2">
                <p className={`text-xs font-medium ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>Choisissez l'identifiant</p>
                {loadingUsernames && <Loader2 size={12} className="animate-spin" />}
              </div>
              <div className="space-y-2">
                {usernameOptions.map((option) => (
                  <label key={option} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name="username"
                      value={option}
                      checked={formData.username === option}
                      onChange={handleChange}
                      className="accent-red"
                    />
                    <code className={`font-mono text-sm font-semibold ${formData.username === option ? (darkMode ? 'text-white' : 'text-navy-900') : (darkMode ? 'text-navy-300' : 'text-navy-600')}`}>
                      {option}
                    </code>
                  </label>
                ))}
              </div>
            </div>
          )}
          {errors.username && <p className="text-xs text-red-500">{errors.username}</p>}

          <div>
            <label className="block text-sm font-medium text-navy-700 dark:text-navy-200 mb-1">Email</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="jean.dupont@thiaroye.sn"
              className="w-full px-4 py-2 rounded-lg border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy-800 text-navy dark:text-white"
            />
            {errors.email && <p className="text-xs text-red-500 mt-1">{errors.email}</p>}
          </div>

          <div>
            <label className="block text-sm font-medium text-navy-700 dark:text-navy-200 mb-1">Numéro de téléphone</label>
            <input
              type="tel"
              name="telephone"
              value={formData.telephone}
              onChange={handleChange}
              placeholder="+221 77 000 00 00"
              className="w-full px-4 py-2 rounded-lg border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy-800 text-navy dark:text-white"
            />
            {errors.telephone && <p className="text-xs text-red-500 mt-1">{errors.telephone}</p>}
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-navy dark:bg-navy-800 text-white py-2.5 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-700 transition disabled:opacity-50"
          >
            {loading ? 'Création...' : 'Créer l\'autorité'}
          </button>
        </form>
      </div>

      {authorities.length > 0 && (
        <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl overflow-hidden">
          <div className="px-6 py-4 border-b border-navy-50 dark:border-navy-800">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-navy dark:text-white">
                Autorités créées ({filteredAuthorities.length} / {authorities.length})
              </h3>
            </div>

            <div className="relative">
              <Search className="absolute left-3 top-3 text-navy-400 dark:text-navy-500" size={18} />
              <input
                type="text"
                placeholder="Rechercher par nom, prénom, email ou identifiant..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy-800 text-navy dark:text-white text-sm"
              />
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-navy-50 dark:border-navy-800 bg-navy-50 dark:bg-navy-800">
                  <th className="px-6 py-3 text-left font-semibold text-navy-700 dark:text-navy-200">Nom</th>
                  <th className="px-6 py-3 text-left font-semibold text-navy-700 dark:text-navy-200">Email</th>
                  <th className="px-6 py-3 text-left font-semibold text-navy-700 dark:text-navy-200">Identifiant</th>
                  <th className="px-6 py-3 text-center font-semibold text-navy-700 dark:text-navy-200">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredAuthorities.length > 0 ? (
                  filteredAuthorities.map((auth) => (
                  <tr key={auth.username} className="border-b border-navy-50 dark:border-navy-800 hover:bg-navy-50 dark:hover:bg-navy-800/50 transition">
                    <td className="px-6 py-4 text-navy dark:text-white font-medium">
                      {auth.first_name} {auth.last_name}
                    </td>
                    <td className="px-6 py-4 text-sm text-navy-600 dark:text-navy-300">
                      {auth.email || '—'}
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <code className="text-xs font-mono text-navy-600 dark:text-navy-300 bg-navy-50 dark:bg-navy-800 px-2 py-1 rounded">
                          {auth.username}
                        </code>
                        <button
                          onClick={() => copyToClipboard(auth.username, `username-${auth.username}`)}
                          className="text-navy-600 dark:text-navy-300 hover:text-navy-900 dark:hover:text-white transition"
                        >
                          {copiedField === `username-${auth.username}` ? <Check size={16} /> : <Copy size={16} />}
                        </button>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-center gap-2">
                        <button
                          onClick={() => setRegenerateConfirmModal(auth.username)}
                          className="text-navy-600 dark:text-navy-300 hover:text-navy-900 dark:hover:text-white transition"
                          title="Régénérer le mot de passe"
                        >
                          <RefreshCw size={16} />
                        </button>
                        <button
                          onClick={() => setDeleteModal(auth.username)}
                          className="text-red-600 dark:text-red-400 hover:text-red-900 dark:hover:text-red-300 transition"
                          title="Supprimer"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="4" className="px-6 py-8 text-center text-navy-600 dark:text-navy-300">
                      Aucune autorité ne correspond à votre recherche
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Modal Résultat Création */}
      {creationResultModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-navy rounded-xl p-6 max-w-md w-full">
            <h3 className="text-lg font-bold text-green-600 dark:text-green-400 mb-2">
              Autorité créée avec succès
            </h3>
            <p className="text-sm text-navy-600 dark:text-navy-300 mb-4">
              Voici les identifiants d'accès pour <strong>{creationResultModal.first_name} {creationResultModal.last_name}</strong>.
              <strong className="block mt-2">Copiez le mot de passe et partagez-le en personne.</strong>
            </p>

            <div className="space-y-3">
              <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-700/30 p-3 rounded-lg">
                <p className="text-xs font-medium text-blue-700 dark:text-blue-300 mb-1">Identifiant</p>
