export default function SignalementsTerrainPage() {
  const [page, setPage] = useState(1);
  const [filter, setFilter] = useState('attente');
  const { data, isLoading } = useSignalements(page);

  const features = data?.results?.features ?? [];
  const filtered = features.filter((f) => {
    if (filter === 'attente') return !f.properties.valide;
    if (filter === 'valides') return f.properties.valide;
    return true;
  });

  return (
    <AutoriteShell>
      <div>
        <h1 className="text-3xl font-extrabold">Signalements terrain</h1>
        <p className="text-base text-navy-600 dark:text-navy-200 mt-0.5">
          Observations transmises par les riverains · {data?.count ?? 0} au total
        </p>
      </div>

      <div className="flex items-center gap-2">
        {FILTERS.map((f) => (
          <button
            key={f.value}
            onClick={() => setFilter(f.value)}
            className={`text-sm font-bold px-3.5 py-2 rounded-md border-[1.5px] transition-colors ${
              filter === f.value
                ? 'bg-navy dark:bg-navy-800 text-white border-navy dark:border-navy-800'
                : 'border-navy-200 dark:border-navy-800 text-navy dark:text-navy-50'
            }`}
          >
            {f.label}
          </button>
        ))}
      </div>

      <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5 flex flex-col gap-3">
        {isLoading ? (
          <p className="text-sm text-navy-400">Chargement…</p>
        ) : filtered.length === 0 ? (
          <p className="text-sm text-navy-400">Aucun signalement dans cette catégorie.</p>
        ) : (
          filtered.map((feature) => <SignalementCard key={feature.id} feature={feature} />)
        )}
      </div>

      {(data?.next || data?.previous) && (
        <div className="flex items-center justify-center gap-3">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={!data?.previous}
            className="flex items-center gap-1 text-sm font-bold text-navy-600 dark:text-navy-200 disabled:opacity-40"
          >
            <ChevronLeft size={14} />
            Précédent
          </button>
          <span className="text-sm text-navy-400">Page {page}</span>
          <button
            onClick={() => setPage((p) => p + 1)}
            disabled={!data?.next}
            className="flex items-center gap-1 text-sm font-bold text-navy-600 dark:text-navy-200 disabled:opacity-40"
          >
            Suivant
            <ChevronRight size={14} />
          </button>
        </div>
      )}
    </AutoriteShell>
  );
}

import { BarChart3 } from 'lucide-react';
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import AutoriteShell from '../desktop/AutoriteShell';
import { useTheme } from '../../theme/ThemeContext';
import { riskInfo } from '../../shared/components/RiskBadge';
import { useZones } from '../../shared/hooks/useZones';
import { useAlertesRecentes } from '../../shared/hooks/useAlertes';
import { useHistoriqueRisque } from '../../shared/hooks/useHistoriqueRisque';

const NIVEAUX_ORDRE = ['vert', 'jaune', 'orange', 'rouge'];

function formatDateShort(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' });
}

export default function StatistiquesPage() {
  const { darkMode } = useTheme();
  const { data: zonesData } = useZones();
  const { data: alertesData } = useAlertesRecentes();
  const { data: historiqueData } = useHistoriqueRisque();

  const gridColor = darkMode ? '#2E4460' : '#EBF0F5';
  const axisColor = darkMode ? '#8AA0B8' : '#4A6480';
  const textColor = darkMode ? '#FFFFFF' : '#000000';
  const tooltipStyle = {
    backgroundColor: darkMode ? '#1B2A40' : '#FFFFFF',
    borderColor: darkMode ? '#2E4460' : '#EBF0F5',
    borderRadius: 8,
    fontSize: 12,
    color: textColor,
  };

  const zonesChartData =
    zonesData?.features?.map((f) => ({
      quartier: f.properties.quartier,
      score: Number(f.properties.score_risque_moyen ?? 0),
      niveau: f.properties.niveau_risque,
    })) ?? [];

  const alertesParNiveau = NIVEAUX_ORDRE.map((niveau) => ({
    niveau,
    label: riskInfo(niveau).label,
    count: alertesData?.results?.filter((a) => a.niveau === niveau).length ?? 0,
  }));

  const historiqueChartData =
    historiqueData?.results
      ?.slice()
      .reverse()
      .map((h) => ({
        date: formatDateShort(h.date_calcul),
        score: Number(h.score_risque ?? 0),
        type: h.type_cible,
      })) ?? [];

  return (
    <AutoriteShell>
      <div>
        <h1 className="text-3xl font-extrabold">Statistiques</h1>
        <p className="text-base text-navy-600 dark:text-navy-200 mt-0.5">Thiaroye-sur-Mer · Vue d’ensemble des indicateurs de risque</p>
      </div>

      <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
        <h3 className="text-base font-bold mb-4 flex items-center gap-2">
          <BarChart3 size={15} />
          Score de risque moyen par zone
        </h3>
        {zonesChartData.length === 0 ? (
          <p className="text-sm text-navy-400">Aucune zone enregistrée pour l’instant.</p>
        ) : (
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={zonesChartData} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                <XAxis dataKey="quartier" stroke={axisColor} fontSize={11} fill={axisColor} />
                <YAxis stroke={axisColor} fontSize={11} domain={[0, 1]} fill={axisColor} />
                <Tooltip contentStyle={tooltipStyle} />
                <Bar dataKey="score" name="Score de risque" radius={[4, 4, 0, 0]}>
                  {zonesChartData.map((entry, i) => (
                    <Cell key={i} fill={riskInfo(entry.niveau).hex} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}
      </div>

      <div className="grid lg:grid-cols-2 gap-5">
        <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
          <h3 className="text-base font-bold mb-4">Alertes par niveau</h3>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={alertesParNiveau} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                <XAxis dataKey="label" stroke={axisColor} fontSize={11} fill={axisColor} />
                <YAxis stroke={axisColor} fontSize={11} allowDecimals={false} fill={axisColor} />
                <Tooltip contentStyle={tooltipStyle} />
                <Bar dataKey="count" name="Alertes" radius={[4, 4, 0, 0]}>
                  {alertesParNiveau.map((entry, i) => (
                    <Cell key={i} fill={riskInfo(entry.niveau).hex} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
          <h3 className="text-base font-bold mb-4">Historique du score de risque</h3>
          {historiqueChartData.length === 0 ? (
            <p className="text-sm text-navy-400">Aucun historique enregistré pour l’instant.</p>
          ) : (
            <div className="h-56">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={historiqueChartData} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                  <XAxis dataKey="date" stroke={axisColor} fontSize={11} />
                  <YAxis stroke={axisColor} fontSize={11} domain={[0, 1]} />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Line type="monotone" dataKey="score" name="Score de risque" stroke="#C0182A" strokeWidth={2} dot={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>
      </div>
    </AutoriteShell>
  );
}

import { useNavigate, Link } from 'react-router-dom';
import { ShieldAlert, Droplet, BarChart3, Send } from 'lucide-react';
import AutoriteShell from '../desktop/AutoriteShell';
import GaugeRisk from '../../shared/components/GaugeRisk';
import RiskBadge from '../../shared/components/RiskBadge';
import { useZones } from '../../shared/hooks/useZones';
import { usePredictions } from '../../shared/hooks/usePredictions';
import { useAlertesRecentes } from '../../shared/hooks/useAlertes';
import { useSignalementsApercu } from '../../shared/hooks/useSignalements';

const NIVEAU_RANK = { vert: 0, jaune: 1, orange: 2, rouge: 3 };

function pickMostAtRiskZone(features) {
  if (!features?.length) return null;
  return [...features]
    .map((f) => ({ id: f.id, ...f.properties }))
    .sort((a, b) => {
      const rankDiff = (NIVEAU_RANK[b.niveau_risque] ?? 0) - (NIVEAU_RANK[a.niveau_risque] ?? 0);
      if (rankDiff !== 0) return rankDiff;
      return Number(b.score_risque_moyen ?? 0) - Number(a.score_risque_moyen ?? 0);
    })[0];
}

function KpiCard({ icon: Icon, label, value, caption, tone = 'navy' }) {
  return (
    <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-lg p-4 flex items-center gap-3">
      <div
        className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${
          tone === 'red' ? 'bg-red-50 dark:bg-red/15 text-red' : 'bg-navy-50 dark:bg-navy-800 text-navy dark:text-navy-50'
        }`}
      >
        <Icon size={18} />
      </div>
      <div className="min-w-0">
        <div className="text-xs font-semibold uppercase text-navy-400 truncate">{label}</div>
        <div className="text-2xl font-extrabold text-navy dark:text-navy-50">{value}</div>
        {caption && <div className="text-xs text-navy-400">{caption}</div>}
      </div>
    </div>
  );
}

export default function TableauDeBordPage() {
  const navigate = useNavigate();

  const { data: zonesData } = useZones();
  const { data: predictions } = usePredictions();
  const { data: alertesData } = useAlertesRecentes();
  const { data: signalementsData } = useSignalementsApercu();

  const zones = zonesData?.features?.map((f) => ({ id: f.id, ...f.properties })) ?? [];
  const topZone = pickMostAtRiskZone(zonesData?.features);
  const zonePrediction = predictions?.find((p) => p.zone?.id === topZone?.id);

  const zonesARisqueEleve = zones.filter((z) => z.niveau_risque === 'orange' || z.niveau_risque === 'rouge').length;
  const scoreRisqueMoyen = zones.length
    ? (zones.reduce((sum, z) => sum + Number(z.score_risque_moyen ?? 0), 0) / zones.length).toFixed(2)
    : '—';

  const recentAlertes = alertesData?.results?.slice(0, 4) ?? [];
  const totalAlertesEnvoyees = alertesData?.count ?? 0;

  const signalementsFeatures = signalementsData?.results?.features ?? [];
  const signalementsEnAttente = signalementsFeatures.filter((f) => !f.properties.valide);

  return (
    <AutoriteShell>
      <div>
        <h1 className="text-3xl font-extrabold">Tableau de bord</h1>
        <p className="text-base text-navy-600 dark:text-navy-200 mt-0.5">Thiaroye-sur-Mer · Supervision temps réel</p>
      </div>

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          <KpiCard icon={ShieldAlert} label="Zones à risque élevé" value={zonesARisqueEleve} tone="red" />
          <KpiCard
            icon={Droplet}
            label="Prédiction IA (24h)"
            value={zonePrediction?.niveau_eau_predit_cm != null ? `${zonePrediction.niveau_eau_predit_cm} cm` : '—'}
            caption={zonePrediction ? `confiance ${Math.round(zonePrediction.confiance)}%` : undefined}
          />
          <KpiCard icon={BarChart3} label="Score de risque moyen" value={scoreRisqueMoyen} caption="échelle 0–1" />
          <KpiCard icon={Send} label="Alertes émises" value={totalAlertesEnvoyees} />
        </div>

        <div className="grid lg:grid-cols-[1.4fr_1fr] gap-5 items-start">
          <GaugeRisk zone={topZone} prediction={zonePrediction} onExploreMap={() => navigate('/autorite/carte')} />

          <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-base font-bold">Alertes récentes</h3>
              <Link to="/autorite/crise" className="text-sm font-bold text-red">
                Gérer
              </Link>
            </div>
            {recentAlertes.length === 0 ? (
              <p className="text-sm text-navy-400">Aucune alerte pour l’instant.</p>
            ) : (
              <div className="flex flex-col gap-3">
                {recentAlertes.map((a) => (
                  <div key={a.id} className="flex items-start gap-3 pb-3 border-b border-navy-50 dark:border-navy-800 last:border-0 last:pb-0">
                    <RiskBadge niveau={a.niveau} className="mt-0.5 flex-shrink-0" />
                    <div className="min-w-0">
                      <div className="text-base font-semibold truncate">{a.zone?.quartier}</div>
                      <p className="text-sm text-navy-600 dark:text-navy-200 line-clamp-2">{a.message}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
          <div className="flex items-center justify-between mb-3">
            <div>
              <h3 className="text-base font-bold">Signalements citoyens à valider</h3>
              <p className="text-sm text-navy-400">Observations transmises par les riverains</p>
            </div>
            <span className="text-sm font-bold text-navy-600 dark:text-navy-200">{signalementsEnAttente.length} en attente</span>
          </div>
          {signalementsEnAttente.length === 0 ? (
            <p className="text-sm text-navy-400">Rien à valider pour l’instant.</p>
          ) : (
            <div className="flex flex-col gap-2">
              {signalementsEnAttente.slice(0, 4).map((f) => (
                <div key={f.id} className="flex items-center gap-3 p-3 border border-navy-50 dark:border-navy-800 rounded-md">
                  <span className="text-[11px] font-bold uppercase px-2.5 py-1 rounded-pill bg-navy-50 dark:bg-navy-800 flex-shrink-0">
                    {f.properties.categorie}
                  </span>
                  <p className="text-sm text-navy-600 dark:text-navy-200 truncate flex-1">{f.properties.description}</p>
                </div>
              ))}
            </div>
          )}
        </div>
    </AutoriteShell>
  );
}

import { memo, useCallback, useMemo } from 'react';
import { Users2, Loader2, CheckCircle2 } from 'lucide-react';
import { useZones } from '../../shared/hooks/useZones';
import { flattenApiErrors } from '../../shared/utils/apiErrors';

function NeighborhoodRelaySectionComponent({ monRelais, relaisZone, setRelaisZone, createRelais, deleteRelais }) {
  const { data: zonesData } = useZones();

  const zones = useMemo(
    () => zonesData?.features?.map((f) => ({ id: f.id, quartier: f.properties.quartier })) ?? [],
    [zonesData]
  );

  const handleZoneChange = useCallback((e) => setRelaisZone(e.target.value), [setRelaisZone]);
  const handleDevenirRelais = useCallback(() => createRelais.mutate({ zone: relaisZone }), [relaisZone, createRelais]);

  return (
    <div className="lg:col-span-2 bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
      <div className="flex items-center gap-2 mb-1">
        <Users2 size={16} className="text-red" />
        <h3 className="text-sm font-bold">Relais de quartier</h3>
      </div>
      <p className="text-xs text-navy-600 dark:text-navy-200 mb-4">
        Devenez volontaire pour être notifié en priorité lors d'une alerte et aider les foyers vulnérables à évacuer.
      </p>

      {monRelais ? (
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div>
            <p className="text-sm font-semibold">
              Inscrit·e pour {zones.find((z) => z.id === monRelais.zone)?.quartier ?? 'votre quartier'}
            </p>
            <span className={`inline-flex items-center gap-1.5 text-xs font-bold mt-1 ${monRelais.verifie ? 'text-risk-vert' : 'text-navy-400'}`}>
              {monRelais.verifie ? <CheckCircle2 size={13} /> : null}
              {monRelais.verifie ? 'Vérifié par une autorité' : 'En attente de vérification'}
            </span>
          </div>
          <button
            type="button"
            onClick={() => deleteRelais.mutate(monRelais.id)}
            disabled={deleteRelais.isPending}
            className="text-xs font-bold text-red border-[1.5px] border-red rounded-md px-3.5 py-2 disabled:opacity-60"
          >
            Se désinscrire
          </button>
        </div>
      ) : (
        <div className="flex items-center gap-3 flex-wrap">
          <select value={relaisZone} onChange={handleZoneChange} className="px-3.5 py-2.5 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy text-sm">
            <option value="">Choisir un quartier</option>
            {zones.map((z) => (
              <option key={z.id} value={z.id}>{z.quartier}</option>
            ))}
          </select>
          <button
            type="button"
            onClick={handleDevenirRelais}
            disabled={!relaisZone || createRelais.isPending}
