// WebSocket Manager avec heartbeat et reconnexion automatique
export class WebSocketManager {
  constructor(url, token, onMessage, onError = null) {
    this.url = url;
    this.token = token;
    this.onMessage = onMessage;
    this.onError = onError;
    this.ws = null;
    this.heartbeatInterval = null;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5;
    this.reconnectDelay = 3000;
    this.isManuallyClosed = false;
  }

  connect() {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) return;

    try {
      this.ws = new WebSocket(this.url, [`Bearer ${this.token}`]);

      this.ws.onopen = () => {
        if (import.meta.env.DEV) console.log('[WS] Connected');
        this.reconnectAttempts = 0;
        this.startHeartbeat();
      };

      this.ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.type === 'pong') return;
          this.onMessage?.(data);
        } catch (error) {
          if (import.meta.env.DEV) console.error('[WS] Parse error:', error);
        }
      };

      this.ws.onerror = (error) => {
        if (import.meta.env.DEV) console.error('[WS] Error:', error);
        this.onError?.(error);
      };

      this.ws.onclose = () => {
        if (import.meta.env.DEV) console.log('[WS] Closed');
        this.stopHeartbeat();
        if (!this.isManuallyClosed) this.attemptReconnect();
      };
    } catch (error) {
      if (import.meta.env.DEV) console.error('[WS] Connection error:', error);
      this.attemptReconnect();
    }
  }

  startHeartbeat() {
    this.heartbeatInterval = setInterval(() => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        this.ws.send(JSON.stringify({ type: 'ping' }));
      }
    }, 30000);
  }

  stopHeartbeat() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  attemptReconnect() {
    if (this.reconnectAttempts < this.maxReconnectAttempts) {
      this.reconnectAttempts++;
      const delay = this.reconnectDelay * Math.pow(1.5, this.reconnectAttempts - 1);
      if (import.meta.env.DEV) console.log(`[WS] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`);
      setTimeout(() => this.connect(), delay);
    } else if (import.meta.env.DEV) {
      console.error('[WS] Max reconnect attempts reached');
    }
  }

  send(type, payload = {}) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type, payload }));
    } else if (import.meta.env.DEV) {
      console.warn('[WS] Not connected, cannot send:', type);
    }
  }

  close() {
    this.isManuallyClosed = true;
    this.stopHeartbeat();
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }

  isConnected() {
    return this.ws?.readyState === WebSocket.OPEN;
  }
}

import { useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useAuth } from '../auth/AuthContext';
import { getAccessToken } from '../auth/tokenStorage';
import { useToast } from '../shared/toast/ToastContext';
import { riskInfo } from '../shared/components/RiskBadge';

// Ouvre le WebSocket ws/alertes/ (broadcast-only, groupe "alertes" — voir
// alertes/consumers.py et alertes/signals.py côté backend) et, à chaque
// nouvelle Alerte créée, invalide le cache React Query concerné et affiche
// un toast. Dégradation totalement silencieuse si Channels/Redis n'est pas
// démarré : l'app reste utilisable, juste sans mise à jour instantanée —
// un rechargement de page ou le polling de React Query prennent le relais.
export function useAlertesSocket() {
  const { isAuthenticated } = useAuth();
  const queryClient = useQueryClient();
  const { showToast } = useToast();

  useEffect(() => {
    if (!isAuthenticated) return undefined;

    const wsUrl = import.meta.env.VITE_WS_URL;
    if (!wsUrl) return undefined;

    // Le consumer côté backend rejette désormais les connexions anonymes
    // (même exigence que GET /api/alertes/ : utilisateur authentifié) — on
    // transmet le token d'accès en query string, seul moyen disponible
    // puisqu'un WebSocket natif ne permet pas d'en-tête Authorization.
    const accessToken = getAccessToken();
    if (!accessToken) return undefined;

    let socket;
    try {
      socket = new WebSocket(wsUrl, [`Bearer ${accessToken}`]);
    } catch {
      return undefined;
    }

    socket.onmessage = (event) => {
      let alerte;
      try {
        alerte = JSON.parse(event.data);
      } catch {
        return;
      }

      queryClient.invalidateQueries({ queryKey: ['alertes'] });

      showToast({
        niveau: alerte.niveau,
        title: `Nouvelle alerte ${riskInfo(alerte.niveau).label.toLowerCase()} — ${alerte.zone?.quartier ?? ''}`,
        message: alerte.message,
      });
    };

    // Pas de reconnexion automatique : une coupure de Redis/Channels ne doit
    // ni spammer la console ni bloquer le reste de l'app.
    socket.onerror = () => {};

    return () => socket.close();
  }, [isAuthenticated, queryClient, showToast]);
}

/**
 * Service WebSocket pour les mises à jour temps réel des prédictions
 * Utilise les WebSockets Django pour les notifications en temps réel
 */

class WebSocketService {
  constructor() {
    this.ws = null;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 10;
    this.reconnectDelay = 3000;
    this.listeners = {
      'zone_updated': [],
      'alert_created': [],
      'weather_updated': [],
      'connection_open': [],
      'connection_close': [],
      'connection_error': []
    };
  }

  connect(url = null) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      return;
    }

    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = url || `${protocol}//localhost:8000/ws/predictions/`;

    try {
      this.ws = new WebSocket(wsUrl);

      this.ws.onopen = () => {
        if (import.meta.env.DEV) console.log('[WebSocket] Connecté');
        this.reconnectAttempts = 0;
        this.emit('connection_open');
      };

      this.ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          this.handleMessage(data);
        } catch (error) {
          if (import.meta.env.DEV) console.error('[WebSocket] Erreur parsing message:', error);
        }
      };

      this.ws.onerror = (error) => {
        if (import.meta.env.DEV) console.error('[WebSocket] Erreur:', error);
        this.emit('connection_error', error);
      };

      this.ws.onclose = () => {
        if (import.meta.env.DEV) console.log('[WebSocket] Disconnecté');
        this.emit('connection_close');
        this.attemptReconnect();
      };
    } catch (error) {
      if (import.meta.env.DEV) console.error('[WebSocket] Erreur création WebSocket:', error);
      this.attemptReconnect();
    }
  }

  handleMessage(data) {
    const { type, payload } = data;

    switch (type) {
      case 'zone_updated':
        this.emit('zone_updated', payload);
        break;
      case 'alert_created':
        this.emit('alert_created', payload);
        break;
      case 'weather_updated':
        this.emit('weather_updated', payload);
        break;
      case 'prediction_made':
        this.emit('prediction_made', payload);
        break;
      default:
        if (import.meta.env.DEV) console.log('[WebSocket] Message inconnu:', type, payload);
    }
  }

  send(type, payload = {}) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type, payload }));
    } else if (import.meta.env.DEV) {
      console.warn('[WebSocket] Non connecté, impossible d\'envoyer:', type);
    }
  }

  on(event, callback) {
    if (this.listeners[event]) {
      this.listeners[event].push(callback);
    }
  }

  off(event, callback) {
    if (this.listeners[event]) {
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    }
  }

  emit(event, data = null) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          if (import.meta.env.DEV) console.error(`[WebSocket] Erreur dans callback ${event}:`, error);
        }
      });
    }
  }

  attemptReconnect() {
    if (this.reconnectAttempts < this.maxReconnectAttempts) {
      this.reconnectAttempts++;
      const delay = this.reconnectDelay * Math.pow(1.5, this.reconnectAttempts - 1);
      if (import.meta.env.DEV) console.log(`[WebSocket] Tentative de reconnexion ${this.reconnectAttempts} dans ${delay}ms`);
      setTimeout(() => this.connect(), delay);
    } else if (import.meta.env.DEV) {
      console.error('[WebSocket] Reconnexion échouée après trop de tentatives');
    }
  }

  disconnect() {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }

  isConnected() {
    return this.ws && this.ws.readyState === WebSocket.OPEN;
  }
}

