import { AlertCircle, CheckCircle2, AlertTriangle } from 'lucide-react';

/**
 * Composant pour afficher les messages de statut avec accessibilité.
 * Utilise aria-live et role="status" pour annoncer aux lecteurs d'écran.
 */
export default function A11yStatusMessage({ type = 'error', message, messages = [], visible = true }) {
  if (!visible || (!message && messages.length === 0)) return null;

  const iconMap = {
    error: AlertCircle,
    success: CheckCircle2,
    warning: AlertTriangle,
  };

  const colorMap = {
    error: 'text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800',
    success: 'text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800',
    warning: 'text-yellow-600 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/20 border-yellow-200 dark:border-yellow-800',
  };

  const Icon = iconMap[type];

  return (
    <div
      role="status"
      aria-live="polite"
      aria-atomic="true"
      className={`flex items-start gap-3 p-4 rounded-lg border ${colorMap[type]}`}
    >
      <Icon size={20} className="flex-shrink-0 mt-0.5" aria-hidden="true" />
      <div className="flex-1">
        {message ? (
          <p className="text-sm">{message}</p>
        ) : (
          <ul className="text-sm space-y-1">
            {messages.map((msg, i) => (
              <li key={i}>{msg}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import { AlertTriangle, X } from 'lucide-react';

/**
 * Composant de confirmation pour actions destructrices
 * Accessible avec ARIA et keyboard navigation
 */
export default function ConfirmDialog({
  isOpen,
  title = "Confirmer l'action",
  message,
  confirmText = "Confirmer",
  cancelText = "Annuler",
  isDangerous = false,
  onConfirm,
  onCancel,
  isLoading = false
}) {
  if (!isOpen) return null;

  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) onCancel();
  };

  return (
    <div
      role="presentation"
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      onClick={handleBackdropClick}
    >
      <div
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="dialog-title"
        aria-describedby="dialog-message"
        className="bg-white dark:bg-navy-900 rounded-lg p-6 max-w-sm w-full shadow-xl border border-navy-100 dark:border-navy-700"
      >
        <div className="flex items-start gap-3 mb-4">
          {isDangerous && (
            <AlertTriangle
              size={24}
              className="text-orange-600 flex-shrink-0 mt-0.5"
              aria-hidden="true"
            />
          )}
          <h2
            id="dialog-title"
            className="text-lg font-bold text-navy-900 dark:text-white"
          >
            {title}
          </h2>
        </div>

        <p
          id="dialog-message"
          className="text-sm text-navy-600 dark:text-navy-200 mb-6"
        >
          {message}
        </p>

        <div className="flex gap-3 justify-end">
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="px-4 py-2.5 rounded-md border border-navy-200 dark:border-navy-700 text-navy-900 dark:text-white font-semibold text-sm hover:bg-navy-50 dark:hover:bg-navy-800 transition disabled:opacity-60"
          >
            {cancelText}
          </button>
          <button
            onClick={onConfirm}
            disabled={isLoading}
            aria-busy={isLoading}
            className={`px-4 py-2.5 rounded-md font-semibold text-sm text-white transition disabled:opacity-60 ${
              isDangerous
                ? 'bg-orange-600 hover:bg-orange-700'
                : 'bg-red hover:bg-red-700'
            }`}
          >
            {isLoading ? 'Veuillez patienter...' : confirmText}
          </button>
        </div>
      </div>
    </div>
  );
}

import { AlertCircle, Info } from 'lucide-react';

/**
 * Messages d'erreur UX-friendly avec explication et suggestions
 */
export default function ErrorMessage({
  error,
  title = "Une erreur s'est produite",
  suggestion,
  type = 'error'
}) {
  if (!error) return null;

  const typeConfig = {
    error: {
      color: 'text-red-600 dark:text-red-400',
      bgColor: 'bg-red-50 dark:bg-red-900/20',
      borderColor: 'border-red-200 dark:border-red-800',
      icon: AlertCircle,
    },
    warning: {
      color: 'text-yellow-600 dark:text-yellow-400',
      bgColor: 'bg-yellow-50 dark:bg-yellow-900/20',
      borderColor: 'border-yellow-200 dark:border-yellow-800',
      icon: Info,
    },
  };

  const config = typeConfig[type];
  const Icon = config.icon;

  // Parse error message (backend sends detailed messages)
  const errorMessage = typeof error === 'string' ? error : error?.message || 'Une erreur inattendue s\'est produite';

  // Friendly error messages
  const friendlyMessages = {
    'Citoyen non trouvé': 'Cet ID de citoyen n\'existe pas. Vérifiez et réessayez.',
    'Identifiant ou mot de passe incorrect': 'Les identifiants saisis sont incorrects. Vérifiez votre connexion.',
    'Permission refusée': 'Vous n\'avez pas les permissions pour effectuer cette action.',
    'Erreur réseau': 'Problème de connexion. Vérifiez votre internet et réessayez.',
    'Délai d\'attente dépassé': 'La requête a pris trop longtemps. Réessayez.',
  };

  // Find friendly message or use original
  const displayMessage = Object.entries(friendlyMessages).find(
    ([key]) => errorMessage.toLowerCase().includes(key.toLowerCase())
  )?.[1] || errorMessage;

  return (
    <div
      role="alert"
      aria-live="assertive"
      className={`flex items-start gap-3 p-4 rounded-lg border ${config.borderColor} ${config.bgColor}`}
    >
      <Icon size={20} className={`${config.color} flex-shrink-0 mt-0.5`} aria-hidden="true" />
      <div className="flex-1 min-w-0">
        <h3 className={`font-semibold text-sm ${config.color} mb-0.5`}>
          {title}
        </h3>
        <p className={`text-sm ${config.color} opacity-90`}>
          {displayMessage}
        </p>
        {suggestion && (
          <p className={`text-xs ${config.color} opacity-75 mt-2 italic`}>
            💡 {suggestion}
          </p>
        )}
      </div>
    </div>
  );
}

import { AlertCircle, CheckCircle2 } from 'lucide-react';

/**
 * Composant de champ de formulaire avec validation inline
 * Affiche feedback en temps réel
 */
export default function FormField({
  id,
  label,
  description,
  value,
  error,
  isValid = null,
  type = 'text',
  placeholder,
  onChange,
  onBlur,
  required = false,
  validator = null,
  ...props
}) {
  // Validation inline en temps réel
  const hasError = error || (validator && value && !validator(value));
  const showValid = isValid === true || (validator && value && validator(value));

  return (
    <label className="block">
      <div className="flex items-center justify-between mb-1.5">
        <span className="block text-sm font-semibold text-navy-900 dark:text-white" id={`${id}-label`}>
          {label}
          {required && <span className="text-red ml-1" aria-label="requis">*</span>}
        </span>
        {showValid && (
          <span className="flex items-center gap-1 text-xs text-green-600 dark:text-green-400">
            <CheckCircle2 size={14} aria-hidden="true" />
            Valide
          </span>
        )}
      </div>

      {description && (
        <span
          className="block text-xs text-navy-500 dark:text-navy-400 mb-1.5"
          id={`${id}-desc`}
        >
          {description}
        </span>
      )}

      {type === 'textarea' ? (
        <textarea
          id={id}
          value={value}
          onChange={onChange}
          onBlur={onBlur}
          placeholder={placeholder}
          aria-labelledby={`${id}-label`}
          aria-describedby={description ? `${id}-desc` : undefined}
          aria-invalid={hasError}
          className={`w-full px-3.5 py-2.5 rounded-md border-[1.5px] transition ${
            hasError
              ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20'
              : showValid
              ? 'border-green-300 dark:border-green-700 bg-green-50 dark:bg-green-900/20'
              : 'border-navy-200 dark:border-navy-800 bg-white dark:bg-navy'
          } text-sm focus:ring-2 focus:ring-inset ${
            hasError ? 'focus:ring-red' : 'focus:ring-green-600'
          } focus:border-transparent`}
          {...props}
        />
      ) : (
        <input
          id={id}
          type={type}
          value={value}
          onChange={onChange}
          onBlur={onBlur}
          placeholder={placeholder}
          aria-labelledby={`${id}-label`}
          aria-describedby={description ? `${id}-desc` : undefined}
          aria-invalid={hasError}
          className={`w-full px-3.5 py-2.5 rounded-md border-[1.5px] transition ${
            hasError
              ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20'
              : showValid
              ? 'border-green-300 dark:border-green-700 bg-green-50 dark:bg-green-900/20'
              : 'border-navy-200 dark:border-navy-800 bg-white dark:bg-navy'
          } text-sm focus:ring-2 focus:ring-inset ${
            hasError ? 'focus:ring-red' : 'focus:ring-green-600'
          } focus:border-transparent`}
          {...props}
        />
      )}

      {hasError && (
        <div className="flex items-start gap-2 mt-1.5">
          <AlertCircle
            size={16}
            className="text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5"
            aria-hidden="true"
          />
          <span
            role="alert"
            className="text-xs text-red-600 dark:text-red-400"
          >
            {error}
          </span>
        </div>
      )}
    </label>
  );
}

