        {visible.refuges &&
          refuges.features.map((f) => {
            const point = pointToLatLng(f.geometry);
            if (!point) return null;
            const typeColors = {
              ecole: '#3C9A5F',
              mosquee: '#8B5CF6',
              centre_sante: '#EF4444',
              mairie: '#F59E0B',
              bâtiment_public: '#06B6D4',
              autre: '#8AA0B8',
            };
            const typeLabel = {
              ecole: 'École',
              mosquee: 'Mosquée',
              centre_sante: 'Centre de santé',
              mairie: 'Mairie',
              bâtiment_public: 'Bâtiment public',
              autre: 'Autre',
