        {visible.signalements &&
          signalements.map((f) => {
            const point = pointToLatLng(f.geometry);
            if (!point) return null;
            return (
              <CircleMarker
                key={`signalement-${f.id}`}
                center={point}
                radius={8}
                pathOptions={{
                  color: '#fff',
                  weight: 2,
                  fillColor: f.properties.valide ? '#C0182A' : '#8AA0B8',
                  fillOpacity: 1,
