            </CircleMarker>
            <FitRoute coordinates={route.coordinates} />
          </>
        )}
      </MapContainer>
    </div>
  );
}

// Les géométries GeoJSON renvoyées par le backend utilisent l'ordre
// [longitude, latitude] ; Leaflet attend [latitude, longitude] partout.
// Ces helpers convertissent chaque type de géométrie en positions
// directement utilisables par <Polygon>/<Polyline>/<CircleMarker>.

function ringToLatLngs(ring) {
  return ring.map(([lon, lat]) => [lat, lon]);
}

export function polygonToLatLngs(geometry) {
  if (!geometry) return [];
  if (geometry.type === 'Polygon') {
    return geometry.coordinates.map(ringToLatLngs);
  }
  if (geometry.type === 'MultiPolygon') {
    return geometry.coordinates.map((polygon) => polygon.map(ringToLatLngs));
  }
  return [];
}

export function lineToLatLngs(geometry) {
  if (!geometry) return [];
  if (geometry.type === 'LineString') {
    return ringToLatLngs(geometry.coordinates);
  }
  if (geometry.type === 'MultiLineString') {
    return geometry.coordinates.map(ringToLatLngs);
  }
  return [];
}

export function pointToLatLng(geometry) {
  if (!geometry || geometry.type !== 'Point') return null;
  const [lon, lat] = geometry.coordinates;
  return [lat, lon];
}

import { createContext, useContext, useState, useCallback, useRef } from 'react';

const NotificationContext = createContext(null);

export function NotificationProvider({ children }) {
  const [notifications, setNotifications] = useState([]);
  const nextIdRef = useRef(1);

  const addNotification = useCallback((notification) => {
    const id = nextIdRef.current++;
    const fullNotification = {
      id,
      timestamp: new Date(),
      ...notification,
    };

    setNotifications((prev) => [fullNotification, ...prev].slice(0, 100));

    return id;
  }, []);

  const removeNotification = useCallback((id) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  return (
    <NotificationContext.Provider value={{ notifications, addNotification, removeNotification }}>
      {children}
    </NotificationContext.Provider>
  );
}

export function useNotifications() {
  const ctx = useContext(NotificationContext);
  if (!ctx) throw new Error('useNotifications must be used inside <NotificationProvider>');
  return ctx;
}

import { useState, useEffect } from 'react';
import client from '../../api/client';

export function useBacktesting() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBacktesting = async () => {
      try {
        setLoading(true);
        const response = await client.get('/inondations/backtesting/');
        setData(response.data);
        setError(null);
      } catch (err) {
        setError(err.response?.data?.erreur || 'Erreur lors du chargement du backtesting');
        setData(null);
      } finally {
        setLoading(false);
      }
    };

    fetchBacktesting();
  }, []);

  return { data, loading, error };
}

import { useState } from 'react';

export function useGeolocation() {
  const [position, setPosition] = useState(null);
  const [status, setStatus] = useState('idle'); // idle | loading | success | error
  const [error, setError] = useState(null);

  const locate = () => {
    if (!navigator.geolocation) {
      setStatus('error');
      setError("Ce navigateur ne permet pas la géolocalisation.");
      return;
    }
    setStatus('loading');
    setError(null);
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setPosition({ lat: pos.coords.latitude, lon: pos.coords.longitude });
        setStatus('success');
      },
      () => {
        setStatus('error');
        setError("Position refusée ou indisponible — activez la géolocalisation puis réessayez.");
      },
      { enableHighAccuracy: true, timeout: 10_000 }
    );
  };

  return { position, status, error, locate };
}

import { useEffect, useState } from 'react';

// Détection de breakpoint côté JS — nécessaire pour choisir quel shell
// monter (mobile vs desktop) sans jamais instancier les deux en même temps
// (ce qui dupliquerait les hooks de données et les effets de chaque page).
export function useMediaQuery(query) {
  const [matches, setMatches] = useState(() =>
    typeof window !== 'undefined' ? window.matchMedia(query).matches : false
  );

  useEffect(() => {
    const mql = window.matchMedia(query);
    const handler = (e) => setMatches(e.matches);
    setMatches(mql.matches);
    mql.addEventListener('change', handler);
    return () => mql.removeEventListener('change', handler);
  }, [query]);

  return matches;
}

