/**
 * Hook pour recevoir les notifications push temps réel via WebSocket.
 * Gère la connexion WebSocket et expose les notifications reçues.
 *
 * Usage:
 * const { isConnected, notifications, lastNotification } = useWebSocketNotifications();
 */
export function useWebSocketNotifications() {
  const { token } = useAuth();
  const { addNotification } = useNotifications();
  const [isConnected, setIsConnected] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [lastNotification, setLastNotification] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!token) return;

    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/ws/alertes/?token=${token}`;

    const ws = new WebSocket(wsUrl);

    // Connexion établie
    ws.onopen = () => {
      if (import.meta.env.DEV) console.log('[WebSocket] Connecté aux notifications');
      setIsConnected(true);
      setError(null);

      // Envoyer un heartbeat tous les 30 secondes
      const heartbeat = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }));
        }
      }, 30000);

      ws.onclose = () => clearInterval(heartbeat);
    };

    // Message reçu
    ws.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data);

        // Ignorer les pongs
        if (payload.type === 'pong') return;

        // Ajouter à la liste des notifications
        const notification = {
          id: Math.random(),
          timestamp: new Date(),
          ...payload,
        };

        setNotifications((prev) => [notification, ...prev].slice(0, 100)); // Garder les 100 dernières
        setLastNotification(notification);

        // Ajouter aussi au système global de notifications
        addNotification(notification);

        // Afficher un toast/son si souhaité
        if (payload.type === 'alerte') {
          if (import.meta.env.DEV) console.warn('[WebSocket] Alerte reçue:', payload.data);
          // Peut déclencher une notification navigateur ici
          showBrowserNotification(payload.data.niveau, `Alerte ${payload.data.zone?.quartier || ''}`);
        } else if (payload.type === 'signalement') {
          if (import.meta.env.DEV) console.log('[WebSocket] Signalement reçu:', payload.data);
        } else if (payload.type === 'sms') {
          if (import.meta.env.DEV) console.log('[WebSocket] SMS reçu:', payload.data);
        }
      } catch (err) {
        if (import.meta.env.DEV) console.error('[WebSocket] Erreur parsing message:', err);
      }
    };

    // Erreur
    ws.onerror = (err) => {
      if (import.meta.env.DEV) console.error('[WebSocket] Erreur:', err);
      setError('Erreur connexion WebSocket');
      setIsConnected(false);
    };

    // Déconnexion
    ws.onclose = () => {
      if (import.meta.env.DEV) console.log('[WebSocket] Déconnecté');
      setIsConnected(false);
    };

    // Cleanup
    return () => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.close();
      }
    };
  }, [token, addNotification]);

  return {
    isConnected,
    notifications,
    lastNotification,
    error,
  };
}

/**
 * Affiche une notification navigateur (Web Notifications API).
 */
function showBrowserNotification(niveau, titre) {
  if (!('Notification' in window)) {
    return;
  }

  if (Notification.permission === 'granted') {
    new Notification(titre, {
      icon: '/logo.png',
      badge: `/badge-${niveau}.png`,
      tag: 'alert',
      requireInteraction: niveau === 'rouge',
    });
  } else if (Notification.permission !== 'denied') {
    // Demander la permission
    Notification.requestPermission().then((permission) => {
      if (permission === 'granted') {
        new Notification(titre);
      }
    });
  }
}

import { createContext, useCallback, useContext, useState } from 'react';
import { X, ShieldAlert } from 'lucide-react';
import { riskInfo } from '../components/RiskBadge';
import { useNotifications } from '../contexts/NotificationContext';

const ToastContext = createContext(null);

let nextId = 1;

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const { addNotification } = useNotifications();

  const dismiss = useCallback((id) => {
    setToasts((list) => list.filter((t) => t.id !== id));
  }, []);

  const showToast = useCallback(
    (toast) => {
      const id = nextId++;
      const toastData = { id, ...toast };
      setToasts((list) => [...list, toastData]);

      // Ajouter aussi au système global de notifications
      addNotification({
        type: 'toast',
        data: {
          titre: toast.title || toast.titre,
          message: toast.message,
        },
        niveau: toast.niveau || 'vert',
      });

      setTimeout(() => dismiss(id), 7000);
    },
    [dismiss, addNotification]
  );

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      <div className="fixed top-4 right-4 z-[2000] flex flex-col gap-2 w-[calc(100%-2rem)] max-w-sm">
        {toasts.map((t) => {
          const { hex } = riskInfo(t.niveau);
          return (
            <div
              key={t.id}
              className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-lg shadow-lg p-4 flex items-start gap-3 animate-[fadeIn_0.2s_ease-out]"
            >
              <div
                className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 text-white"
                style={{ backgroundColor: hex ?? '#1B2A40' }}
              >
                <ShieldAlert size={15} />
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-sm font-bold text-navy dark:text-navy-50">{t.title}</p>
                {t.message && <p className="text-xs text-navy-600 dark:text-navy-200 mt-0.5">{t.message}</p>}
              </div>
              <button onClick={() => dismiss(t.id)} className="text-navy-400 hover:text-navy dark:hover:text-navy-50 flex-shrink-0">
                <X size={14} />
              </button>
            </div>
          );
        })}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast doit être utilisé à l’intérieur de <ToastProvider>.');
  return ctx;
}

// DRF renvoie les erreurs de validation sous la forme { champ: [messages] }
// (ou { detail: "..." } pour les erreurs génériques) — on aplatit tout ça en
// une simple liste de messages affichables, quel que soit le champ en cause.
export function flattenApiErrors(error) {
  const data = error?.response?.data;
  if (!data) return ["Une erreur est survenue. Veuillez réessayer."];
  if (typeof data === 'string') return [data];
  if (data.detail) return [data.detail];

  const messages = Object.values(data).flat().filter(Boolean);
  return messages.length ? messages : ['Une erreur est survenue. Veuillez réessayer.'];
}

import { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext(null);

export function ThemeProvider({ children }) {
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('mbeund_theme');
    // Clair par défaut, comme dans les maquettes validées.
    return saved ? saved === 'dark' : false;
  });

  useEffect(() => {
    localStorage.setItem('mbeund_theme', darkMode ? 'dark' : 'light');
    document.documentElement.classList.toggle('dark', darkMode);
  }, [darkMode]);

  const toggleTheme = () => setDarkMode((d) => !d);

  return (
    <ThemeContext.Provider value={{ darkMode, setDarkMode, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme doit être utilisé à l’intérieur de <ThemeProvider>.');
  return ctx;
}

import { Sun, Moon } from 'lucide-react';
import { useTheme } from './ThemeContext';

export default function ThemeToggle({ className = '' }) {
  const { darkMode, toggleTheme } = useTheme();

  return (
    <button
      type="button"
      onClick={toggleTheme}
      aria-label={darkMode ? 'Passer en mode clair' : 'Passer en mode sombre'}
      className={`w-9 h-9 rounded-full border border-navy-200 dark:border-navy-800 flex items-center justify-center text-navy-600 dark:text-navy-200 hover:bg-navy-50 dark:hover:bg-navy-800 transition-colors ${className}`}
    >
      {darkMode ? <Sun size={16} /> : <Moon size={16} />}
    </button>
  );
}
